const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const BRL=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(n)||0);
const fmt=(n,d=2)=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:d}).format(Number(n)||0);
const dateBR=d=>d?d.split('-').reverse().join('/'): '—';
const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
const safeTheme=()=>{try{return localStorage.getItem('metrics-theme')||'dark';}catch{return 'dark';}};
const NAV=[['dashboard','▦','Visão geral'],['ai','✧','Metrics AI'],['wallet','▤','Carteira'],['watch','☆','Desejos'],['assets','▥','Analisar'],['quotes','◈','Preços'],['performance','↗','Evolução'],['radar','◎','Radar e fundamentos'],['sources','◉','Fontes e CVM'],['classes','▥','Classes e exterior'],['notices','▧','Comunicados'],['income','◴','Proventos'],['calendar','▣','Calendário'],['sim','◫','Simulador'],['multi','◇','Carteira futura'],['import','⇧','Importar B3'],['docs','▧','Documentos'],['tax','▣','Relatórios'],['portfolios','▣','Carteiras'],['extensions','◇','Extensões'],['settings','⚙','Ajustes']];
let S={instruments:[],fixedIncome:[],foreignTrades:[],foreignPositions:[],fxRates:[],taxEvidence:[],notices:[],transactions:[],watchlist:[],messages:[],quotes:[],profiles:[],events:[],snapshots:[],facts:null,futureEvents:[],documents:[],imports:[],summary:{positions:[],holdingCost:0,dividends:0,realized:0,holdings:0},analytics:{positions:[],dividendsByMonth:[],dividendsByTicker:[],missingQuotes:[]},page:'dashboard',ai:{provider:'ollama',model:'qwen2.5:3b',key:'',context:false},theme:safeTheme(),busy:false,preview:null,stages:[{months:60,amount:400},{months:120,amount:500}],lastSimulation:null,multiAssets:[{ticker:'GGRC11',price:9.19,dividend:0.10,weight:50},{ticker:'VGIR11',price:9.58,dividend:0.13,weight:50}],lastMulti:null,risk:[],settings:{},taxLedger:null,marketPreview:null,marketKey:'',performance:null,marketAuto:false,marketRefreshing:false,quality:null,radar:null,providerPreview:null,providerKey:'',rankSort:'DY',portfolios:[],portfolioId:null,extensions:[],extensionViews:{},transactionAudit:[],editingTransactionId:null,cvm:null,cvmQuarterly:null,providerDividends:null,sourceHealth:null,taxWorkpaper:null,coverage:null,incomeReconciliation:null};
function toast(s,err=false){$('.toast')?.remove();const div=document.createElement('div');div.className='toast'+(err?' error':'');div.textContent=s;document.body.append(div);setTimeout(()=>div.remove(),5600);}
async function api(url,{method='GET',data}={}){const res=await fetch(url,{method,headers:{'X-Metrics-Local':'1',...(S.portfolioId?{'X-Metrics-Portfolio-ID':S.portfolioId}:{}),...(data?{'Content-Type':'application/json'}:{})},body:data?JSON.stringify(data):undefined});const json=await res.json();if(!res.ok)throw Error(json.error||'Falha no serviço local.');return json;}
async function update(){
 const sequence=S._loadSequence=(S._loadSequence||0)+1;
 const p=await api('/api/portfolios');if(sequence!==S._loadSequence)return;
 S.portfolios=p.portfolios;if(!S.portfolioId||!p.portfolios.some(x=>x.id===S.portfolioId))S.portfolioId=p.activePortfolioId;
 const state=await api('/api/state');if(sequence!==S._loadSequence)return;Object.assign(S,state);
 // Queries independent: parallel, individually isolated, and wallet-scoped by api().
 const sources=[['risk','/api/risk'],['facts','/api/insights'],['future','/api/future-income'],['performance','/api/performance'],['quality','/api/quality'],['radar','/api/radar'],['cvm','/api/official/cvm'],['coverage','/api/data/coverage'],['reconcile','/api/income/reconcile'],['quarter','/api/official/cvm-quarterly'],['provider','/api/official/provider-dividends'],['health','/api/data/health-v13']];
 const results=await Promise.allSettled(sources.map(x=>api(x[1])));
 if(sequence!==S._loadSequence)return;
 const m=Object.fromEntries(sources.map(([k],i)=>[k,results[i].status==='fulfilled'?results[i].value:null]));
 S.risk=m.risk||[];S.facts=m.facts;S.futureEvents=m.future?.events||[];S.performance=m.performance;S.quality=m.quality;S.radar=m.radar;S.cvm=m.cvm;S.coverage=m.coverage;S.incomeReconciliation=m.reconcile;S.cvmQuarterly=m.quarter;S.providerDividends=m.provider;S.sourceHealth=m.health;
}

const opt=(a,b)=>a===b?'selected':'';
function head(k,title,description,action=''){return `<div class="page-head"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p class="subheading">${description}</p></div>${action}</div>`;}
function card(label,value,foot='',cls=''){return `<div class="card metric"><div class="metric-label">${label}</div><div class="metric-value ${cls}">${value}</div><div class="metric-foot">${foot}</div></div>`;}
function shell(){document.documentElement.classList.toggle('light',S.theme==='light');return `<div class="shell"><aside class="sidebar"><div class="brand"><img src="/logo.svg" class="brand-logo" alt="Metrics"><div><div class="brand-name">Metrics</div><div class="brand-small">INVESTIMENTOS</div></div></div><nav class="nav">${NAV.map(([id,ico,name])=>`<button class="item ${S.page===id?'active':''}" data-nav="${id}"><span class="nav-icon">${ico}</span><span>${name}</span></button>`).join('')}</nav><div class="side-bottom"><div class="status-box"><div class="status-line"><span class="dot"></span> Seus dados ficam neste dispositivo</div><p class="muted micro">Sem conexão à corretora · IA opcional</p></div><p class="side-footer">Metrics v2.8 Integrity · local-first</p></div></aside><main class="main"><header class="topbar"><span class="top-heading">Metrics / ${NAV.find(n=>n[0]===S.page)?.[2]}</span><div class="top-right"><label class="micro muted" for="portfolio-switch">Carteira</label><select id="portfolio-switch" class="input" aria-label="Selecionar carteira" style="width:190px;max-width:24vw">${(S.portfolios||[]).map(p=>`<option value="${esc(p.id)}" ${p.id===S.portfolioId?'selected':''}>${esc(p.name)}</option>`).join('')}</select><span class="pill">◉ Local ${S.encrypted?'· criptografado':'· sem senha'}</span><button class="btn smol" id="theme">${S.theme==='dark'?'☀ Claro':'☾ Escuro'}</button></div></header><div id="content" class="page">${pages[S.page]()}</div></main></div>`;}
function positionsTable(){const rows=S.analytics.positions;if(!rows.length)return `<div class="empty">Sem posições abertas. Adicione uma compra na carteira.</div>`;return `<div class="table-wrap"><table class="table"><thead><tr><th>Ativo</th><th>Quantidade</th><th>Preço médio</th><th>Custo</th><th>Valor estimado*</th><th>Resultado*</th></tr></thead><tbody>${rows.map(p=>`<tr><td><span class="asset-pill">${esc(p.ticker)}</span></td><td>${fmt(p.quantity,6)}</td><td>${BRL(p.average)}</td><td>${BRL(p.cost)}</td><td>${p.marketValue===null?'—':BRL(p.marketValue)}</td><td class="${p.unrealized>=0?'positive':'danger-text'}">${p.unrealized===null?'—':BRL(p.unrealized)}</td></tr>`).join('')}</tbody></table></div><p class="footline">* Preços manuais, fechamentos históricos ou feed atrasado. Consulte a data-base e a origem na aba Preços. Não são cotações em tempo real.</p>`;}
function txTable(rows,remove=true){if(!rows.length)return '<div class="empty">Nenhum lançamento neste período.</div>';return `<div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Ativo</th><th>Tipo</th><th>Quantidade / Valor</th><th>Origem</th>${remove?'<th>Ações</th>':''}</tr></thead><tbody>${rows.map(t=>`<tr><td>${dateBR(t.date)}</td><td><span class="asset-pill">${esc(t.ticker)}</span></td><td>${t.type==='BUY'?'Compra':t.type==='SELL'?'Venda':t.type==='JCP'?'JCP':t.type==='AMORTIZATION'?'Amortização':t.type==='SPLIT'?'Desdobramento':t.type==='REVERSE_SPLIT'?'Grupamento':t.type==='BONUS'?'Bonificação':'Dividendo'}</td><td>${['DIVIDEND','JCP','AMORTIZATION'].includes(t.type)?BRL(t.amount):['SPLIT','REVERSE_SPLIT'].includes(t.type)?'Fator: '+fmt(t.factor,8):t.type==='BONUS'?fmt(t.quantity,6)+' cotas · custo '+BRL(t.basis):fmt(t.quantity,6)+' × '+BRL(t.price)}</td><td>${esc(t.source||'manual')}</td>${remove?`<td><div class="inline-buttons"><button class="btn smol" data-edit-tx="${esc(t.id)}" aria-label="Editar lançamento de ${esc(t.ticker)}">Editar</button><button class="btn smol danger" data-remove-tx="${esc(t.id)}" aria-label="Excluir lançamento de ${esc(t.ticker)}">Excluir</button></div></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function chart(data,yLabel='R$'){if(!data.length)return '<div class="empty">Sem dados registrados.</div>';const max=Math.max(1,...data.map(x=>x[1]));return `<div class="bar-chart" role="img" aria-label="Gráfico de ${esc(yLabel)}"><div class="bar-track">${data.map(([label,value])=>`<div class="bar-entry" title="${esc(label)}: ${BRL(value)}"><div class="bar-fill" style="height:${Math.max(2,value/max*100)}%"></div><span>${esc(label.slice(-7))}</span></div>`).join('')}</div></div>`;}
function snapshotCard(){const snap=[...(S.snapshots||[])].sort((a,b)=>b.asOf.localeCompare(a.asOf))[0];if(!snap)return '';return `<section class="card spaced"><div class="card-header"><h2>Posição importada da B3 em ${dateBR(snap.asOf)}</h2><button class="btn link" data-nav="import">Conferir arquivo →</button></div><p class="small muted">Extrato de custódia: ${esc(snap.source)}. Estas quantidades NÃO são compras, não geram preço médio nem lucro fiscal. Verifique diferenças com os lançamentos manuais.</p><div class="table-wrap"><table class="table"><thead><tr><th>Ticker</th><th>Quantidade no extrato</th><th>Quantidade lançada</th><th>Diferença</th></tr></thead><tbody>${snap.positions.slice(0,80).map(x=>{const tx=S.summary.positions.find(p=>p.ticker===x.ticker);const q=tx?.quantity??null;return `<tr><td>${esc(x.ticker)}</td><td>${fmt(x.quantity,6)}</td><td>${q===null?'sem histórico':fmt(q,6)}</td><td>${q===null?'não conciliado':fmt(x.quantity-q,6)}</td></tr>`;}).join('')}</tbody></table></div></section>`;}
function dashboard(){const a=S.analytics,events=(S.events||[]).filter(e=>e.date>=today()).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,4),month=today().slice(0,7),inMonth=Object.fromEntries(a.dividendsByMonth)[month]||0;return `${head('MEU PATRIMÔNIO','Visão geral','Seus números de verdade, com contexto e sem dados inventados.')}<div class="hero"><div><h2>Investimentos sob seu controle.</h2><p>Registre operações, importe extratos, acompanhe proventos e faça perguntas à IA sobre o que você possui e deseja comprar.</p><div class="row-actions"><button class="btn primary" data-nav="ai">✧ Abrir Metrics AI</button><button class="btn" data-nav="wallet">+ Nova operação</button></div></div><div class="hero-art">◈</div></div><div class="metrics">${card('Custo das posições',BRL(S.summary.holdingCost),'Não é valor atual de mercado')}${card('Dividendos no mês',BRL(inMonth),'Apenas proventos registrados','positive')}${card('Valor de mercado coberto',a.marketValueComplete?BRL(a.marketValue):'Incompleto',a.marketValueComplete?'Com preços registrados, não ao vivo':'Há ativos sem cotação; não somar como patrimônio total','blue')}${card('Posições abertas',fmt(S.summary.holdings,0),'Ativos em carteira')}${card('Na lista de desejos',fmt(S.watchlist.length,0),'Monitorados pela IA','blue')}</div><div class="grid-2"><section class="card"><div class="card-header"><h2>Carteira atual</h2><button class="btn link" data-nav="wallet">Gerenciar →</button></div>${positionsTable()}<div class="section-note">${a.missingQuotes?.length?'Sem preço manual em: '+esc(a.missingQuotes.join(', '))+'.':'Preços manuais podem ficar desatualizados.'} Não usamos cotação fictícia.</div></section><section class="card"><div class="card-header"><h2>Proventos registrados por mês</h2><button class="btn link" data-nav="income">Ver detalhes →</button></div>${chart((a.dividendsByMonth||[]).slice(-9))}</section></div><section class="card spaced"><div class="card-header"><h2>Próximos pagamentos cadastrados</h2><button class="btn link" data-nav="calendar">Abrir calendário →</button></div>${events.length?events.map(e=>`<div class="watch-row"><div><b>${esc(e.ticker)}</b> <span class="small muted">${dateBR(e.date)}</span><p class="small">${BRL(e.perShare)} por cota · ${e.kind==='ESTIMADO'?'estimativa pessoal':'informado como confirmado'}</p></div></div>`).join(''):'<div class="empty">Nenhum pagamento futuro cadastrado.</div>'}</section>${snapshotCard()}<section class="card spaced"><div class="card-header"><h2>Últimas operações</h2><button class="btn link" data-nav="wallet">Histórico completo →</button></div>${txTable([...S.transactions].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6),false)}</section>`;}
function transactionEditPanel(){
 const t=S.transactions.find(x=>x.id===S.editingTransactionId);
 if(!t)return '';
 const income=['DIVIDEND','JCP','AMORTIZATION'].includes(t.type),split=['SPLIT','REVERSE_SPLIT'].includes(t.type),bonus=t.type==='BONUS',trade=['BUY','SELL'].includes(t.type);
 return `<section class="card spaced" id="tx-edit-panel" tabindex="-1"><div class="card-header"><div><h2>Corrigir lançamento: ${esc(t.ticker)}</h2><p class="small muted">Edite a operação original, sem registrar uma segunda compra. As posições, o preço médio e os relatórios serão recalculados.</p></div><button type="button" class="btn smol" id="cancel-edit-tx">Cancelar</button></div>
 <form id="tx-edit-form"><div class="form-grid two">
 <label class="field">Tipo de operação<input class="input" value="${esc({BUY:'Compra',SELL:'Venda',DIVIDEND:'Dividendo',JCP:'JCP',AMORTIZATION:'Amortização',SPLIT:'Desdobramento',REVERSE_SPLIT:'Grupamento',BONUS:'Bonificação'}[t.type]||t.type)}" disabled></label>
 <label class="field">Ticker<input class="input" name="ticker" value="${esc(t.ticker)}" maxlength="24" required></label>
 <label class="field">Data verdadeira da operação<input class="input" name="date" type="date" value="${esc(t.date)}" required></label>
 ${trade?`<label class="field">Quantidade<input class="input" name="quantity" type="number" min="0.000001" step="any" value="${esc(t.quantity)}" required></label><label class="field">Preço unitário (R$)<input class="input" name="price" type="number" min="0.000001" step="any" value="${esc(t.price)}" required></label><label class="field">Taxas (R$)<input class="input" name="fee" type="number" min="0" step="any" value="${esc(t.fee)}" required></label>`:''}
 ${income?`<label class="field">Valor recebido (R$)<input class="input" name="amount" type="number" min="0.01" step="any" value="${esc(t.amount)}" required></label>`:''}
 ${t.type==='AMORTIZATION'?`<label class="field">Reduzir o custo fiscal?<select class="input" name="adjustCost"><option value="false" ${!t.adjustCost?'selected':''}>Não, requer conferência</option><option value="true" ${t.adjustCost?'selected':''}>Sim, comprovado por informe</option></select></label>`:''}
 ${split?`<label class="field">Fator do evento<input class="input" name="factor" type="number" min="0.000001" step="any" value="${esc(t.factor)}" required></label>`:''}
 ${bonus?`<label class="field">Quantidade bonificada<input class="input" name="quantity" type="number" min="0.000001" step="any" value="${esc(t.quantity)}" required></label><label class="field">Custo fiscal atribuído (R$)<input class="input" name="basis" type="number" min="0" step="any" value="${esc(t.basis||0)}"></label>`:''}
 <label class="field wide">Observação<input class="input" name="notes" maxlength="300" value="${esc(t.notes||'')}"></label></div>
 <div class="form-actions"><button class="btn" type="button" id="cancel-edit-tx-bottom">Cancelar</button><button class="btn primary" type="submit">Salvar correção</button></div></form>
 <p class="small muted">Origem: ${esc(t.source||'manual')}. Se veio de uma importação, confira o lote depois da correção. Corrigir um lançamento não altera o documento original da B3.</p></section>`;
}
function undoTransactionPanel(){const a=(S.transactionAudit||[]).filter(x=>!x.undoneAt).at(-1);return a&&['CREATE','EDIT','DELETE'].includes(a.action)?`<div class="section-note undo-trade" role="status"><strong>Última ação: ${esc({CREATE:'Adição',EDIT:'Correção',DELETE:'Exclusão'}[a.action]||a.action)} de ${esc(a.ticker||'ativo')}</strong> · ${esc(a.at?.slice(0,16).replace('T',' ')||'')} <button class="btn smol" id="undo-last-tx">↶ Desfazer última ação</button><p class="small muted">O desfazer permanece disponível após reiniciar. Para segurança, só a última alteração pode ser desfeita.</p></div>`:'';}
function wallet(){return `${head('CARTEIRA REAL','Meus investimentos','Lançamentos manuais, histórico auditável e preço médio ponderado.')}
<div class="metrics">${card('Custo atual',BRL(S.summary.holdingCost),'Custo histórico')}${card('Dividendos acumulados',BRL(S.summary.dividends),'Registrados manualmente','positive')}${card('Resultado em vendas',BRL(S.summary.realized),'Antes dos impostos')}${card('Ativos com saldo',S.summary.holdings,'Cotas ou ações')}</div>
<div class="grid-2"><section class="card"><h2>Posições</h2>${positionsTable()}</section><section class="card"><h2>Adicionar lançamento</h2><p class="subheading">Registre o que realmente aconteceu; a lista de desejos fica separada.</p><form id="tx-form"><div class="form-grid two"><label class="field">Operação<select class="input" name="type" id="tx-type"><option value="BUY">Compra</option><option value="SELL">Venda</option><option value="DIVIDEND">Dividendos / rendimentos</option><option value="JCP">Juros sobre capital próprio (JCP)</option><option value="AMORTIZATION">Amortização de capital (revisão fiscal)</option></select></label><label class="field">Ticker<input class="input" name="ticker" placeholder="MXRF11" required maxlength="24"></label><label class="field">Data<input class="input" type="date" name="date" value="${today()}" required></label><label class="field" data-trade>Quantidade<input class="input" name="quantity" type="number" min="0.000001" step="any" value="1"></label><label class="field" data-trade>Preço unitário (R$)<input class="input" name="price" type="number" min="0.0001" step="any" placeholder="9.50"></label><label class="field" data-trade>Taxas (R$)<input class="input" name="fee" type="number" min="0" step="any" value="0"></label><label class="field wide hide" id="tx-dividend">Provento recebido (R$)<input class="input" name="amount" type="number" step="any" min="0.01"></label><label class="field wide">Observação<input class="input" name="notes" maxlength="300" placeholder="Opcional"></label></div><div class="form-actions"><button class="btn primary" type="submit">Salvar lançamento</button></div></form></section></div>${undoTransactionPanel()}${transactionEditPanel()}<section class="card spaced"><div class="card-header"><h2>Histórico completo</h2><span class="pill">${S.transactions.length} registros</span></div><label class="field">Buscar lançamento por data, ativo ou tipo<input class="input" type="search" id="tx-history-filter" placeholder="Ex.: MXRF11, compra, 2026" autocomplete="off"></label><div id="tx-history-list">${txTable([...S.transactions].sort((a,b)=>b.date.localeCompare(a.date)))}</div></section>`;}
function watch(){return `${head('PLANEJAMENTO','Lista de desejos','Seus próximos investimentos, separados das compras que já realizou.')}
<div class="grid-2"><section class="card"><div class="card-header"><h2>Ativos para estudar</h2><span class="pill">${S.watchlist.length} tickers</span></div>${S.watchlist.length?S.watchlist.map(w=>`<div class="watch-row"><div><div class="watch-code">${esc(w.ticker)}</div><div class="small muted">Prioridade: ${esc(w.priority)} · Preço-alvo: ${w.target?BRL(w.target):'não definido'} · Aporte: ${w.budget?BRL(w.budget):'não definido'}</div>${w.notes?`<p class="small">${esc(w.notes)}</p>`:''}${S.quotes.find(q=>q.ticker===w.ticker)&&w.target&&S.quotes.find(q=>q.ticker===w.ticker).price<=w.target?'<p class="small positive">● Preço-alvo atingido no preço informado manualmente (não ao vivo)</p>':''}</div><div class="inline-buttons"><button class="btn smol" data-edit-watch="${esc(w.id)}">Editar</button><button class="btn smol danger" data-remove-watch="${esc(w.id)}">Excluir</button></div></div>`).join(''):'<div class="empty">Adicione ativos que deseja analisar ou comprar futuramente.</div>'}<div class="section-note">A Metrics AI consulta esta lista apenas se você autorizar o contexto. Registrar um desejo nunca altera sua carteira.</div></section><section class="card"><h2>Adicionar investimento desejado</h2><form id="watch-form"><div class="form-grid two"><label class="field">Ticker<input class="input" name="ticker" required placeholder="GGRC11"></label><label class="field">Prioridade<select class="input" name="priority"><option value="alta">Alta</option><option value="media" selected>Média</option><option value="baixa">Baixa</option></select></label><label class="field">Preço de interesse<input class="input" name="target" type="number" step="any" min="0.01"></label><label class="field">Aporte planejado<input class="input" name="budget" type="number" step="any" min="0.01"></label><label class="field wide">Motivo / objetivo<textarea class="input" name="notes" maxlength="500" rows="3" placeholder="Por que acompanhar este investimento?"></textarea></label></div><div class="form-actions"><button class="btn primary" type="submit">Adicionar à lista</button></div></form></section></div>`;}
function fundWarnings(p){const r=(S.risk||[]).find(x=>x.ticker===p.ticker);if(!r)return '';return `<details class="risk-details"><summary>Triagem de riscos e dados faltantes</summary>${r.warnings.map(x=>`<p class="danger-text small">⚠ ${esc(x)}</p>`).join('')}${r.positive.map(x=>`<p class="positive small">✓ ${esc(x)}</p>`).join('')}${r.missing.map(x=>`<p class="small muted">? ${esc(x)}</p>`).join('')}<p class="small muted">Não é uma nota de segurança nem recomendação.</p></details>`;}
function assets(){const list=S.profiles||[];return `${head('FICHAS FINANCEIRAS','Análise de ativos','Cadastre fundamentos verificados em relatórios. Nenhum indicador é inventado.')}
<div class="grid-2"><section class="card"><div class="card-header"><h2>Ativos pesquisados</h2><span class="pill">${list.length} fichas</span></div>${list.length?list.map(p=>`<div class="watch-row"><div><b>${esc(p.ticker)} · ${esc(p.name||p.type)}</b><p class="small muted">${esc(p.type.replace('_',' '))} · ${esc(p.sector||'setor não informado')} · Fonte: ${esc(p.source)} · ${esc(p.date||'sem data')}</p><p class="small">Patrimônio: ${p.equity===null?'—':BRL(p.equity)} · Ativos: ${p.assets??'—'} · Ocupados: ${p.occupied??'—'} · DY 12m: ${p.dy12??'—'}%</p>${p.notes?`<p class="small muted">${esc(p.notes)}</p>`:''}${fundWarnings(p)}</div><button class="btn smol danger" data-remove-profile="${esc(p.ticker)}">Excluir</button></div>`).join(''):'<div class="empty">Ainda não há fichas. Você pode registrar números verificados nos relatórios que possui.</div>'}</section><section class="card"><h2>Cadastrar / atualizar ficha</h2><p class="lead">Indicadores são opcionais. Use valores de relatórios identificados por data e fonte.</p><form id="profile-form"><div class="form-grid two"><label class="field">Ticker<input class="input" name="ticker" placeholder="GGRC11" required></label><label class="field">Tipo<select class="input" name="type"><option value="FII_TIJOLO">FII tijolo</option><option value="FII_PAPEL">FII papel</option><option value="FII_HIBRIDO">FII híbrido</option><option value="ACAO">Ação</option><option value="ETF">ETF</option><option value="RENDA_FIXA">Renda fixa</option><option value="OUTRO">Outro</option></select></label><label class="field">Nome<input class="input" name="name"></label><label class="field">Setor / foco<input class="input" name="sector" placeholder="Logística, shoppings, CRI..."></label><label class="field">Gestora<input class="input" name="manager"></label><label class="field">Patrimônio líquido (R$)<input class="input" name="equity" type="number" step="any" min="0"></label><label class="field">Qtd. imóveis / operações<input class="input" name="assets" type="number" step="1" min="0"></label><label class="field">Imóveis ocupados<input class="input" name="occupied" type="number" step="1" min="0"></label><label class="field">Vacância (%)<input class="input" name="vacancy" type="number" step="any" min="0" max="100"></label><label class="field">Dividendo / cota<input class="input" name="dividend" type="number" step="any" min="0"></label><label class="field">DY 12m (%)<input class="input" name="dy12" type="number" step="any" min="0"></label><label class="field">Dívidas (R$)<input class="input" name="debt" type="number" step="any" min="0"></label><label class="field">Data-base<input class="input" name="date" type="date"></label><label class="field">Fonte do dado<input class="input" name="source" placeholder="Relatório da gestora, página..."></label><label class="field wide">Observações verificadas<textarea class="input" name="notes" rows="3" maxlength="1200"></textarea></label></div><div class="form-actions"><button class="btn primary">Salvar ficha</button></div></form></section></div>`;}
function lineHistory(rows){if(rows.length<2)return '<div class="empty">Importe ao menos dois dias completos de preços para desenhar a trajetória.</div>';
 const min=Math.min(...rows.map(p=>p.value)),max=Math.max(...rows.map(p=>p.value)),den=Math.max(.01,max-min);
 const loc=rows.map((p,i)=>({date:p.date,value:p.value,x:i/(rows.length-1)*760,y:170-(p.value-min)/den*145}));
 const groups=[];let group=[];
 for(const point of loc){if(group.length && (Date.parse(point.date+'T00:00:00Z')-Date.parse(group.at(-1).date+'T00:00:00Z'))/86400000>4){groups.push(group);group=[];}group.push(point);}if(group.length)groups.push(group);
 const lines=groups.map(g=>g.length<2?'':`<polyline points="${g.map(p=>p.x.toFixed(1)+','+p.y.toFixed(1)).join(' ')}" fill="none" stroke="#4b8cff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>`).join('');
 const dots=loc.map(p=>`<circle cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="3" fill="#4b8cff"><title>${esc(p.date+' · '+BRL(p.value))}</title></circle>`).join('');
 return `<svg viewBox="0 0 780 205" role="img" aria-label="Evolução das posições em datas com cobertura completa; lacunas interrompem a curva" style="width:100%;height:auto;max-height:300px"><line x1="0" y1="178" x2="780" y2="178" stroke="currentColor" opacity=".2"/>${lines}${dots}</svg><div class="row small muted"><span>${dateBR(rows[0].date)} · ${BRL(rows[0].value)}</span><span>${dateBR(rows.at(-1).date)} · ${BRL(rows.at(-1).value)}</span></div><p class="small muted">Linhas interrompidas indicam intervalos sem cobertura histórica suficiente.</p>`;
}
function performance(){const p=S.performance||{},last=p.lastComplete;
 return `${head('EVOLUÇÃO','Patrimônio e comparação com CDI','Histórico auditável por data. Sem datas, preços e compras completas, o Metrics não inventa uma curva de retorno.')}
<div class="metrics">${card('Último patrimônio calculável',last?BRL(last.value):'Sem dados',last?'Posições cobertas em '+dateBR(last.date):'É necessário histórico de preços de todos os ativos')}${card('Dias com cotação completa',fmt(p.completeDays||0,0),'Faltam séries para períodos sem cotação')}${card('Retorno aproximado',p.approximateTwrPercent==null?'Indisponível':fmt(p.approximateTwrPercent,2)+'%',p.linkedPeriods?'Calculado apenas nos intervalos ligados':'Sem sequência suficiente')}${card('CDI no período',p.benchmark?fmt(p.benchmark.cumulativePercent,2)+'%':'Sem dados',p.benchmark?'SGS 12 importado/consultado':'Busque CDI oficial para comparar')}</div>
<div class="grid-2"><section class="card"><h2>Valor das posições, nas datas com cobertura</h2>${lineHistory((p.points||[]).filter(x=>x.complete))}<p class="section-note">${esc(p.warning||'Sem histórico suficiente.')} Atenção: evolução do valor investido NÃO é igual à rentabilidade, porque há novos aportes e saques.</p></section><section class="card"><h2>Comparadores oficiais</h2><p class="subheading">Carregue a série CDI diária do Banco Central (SGS 12). O índice acumulado é exibido somente no intervalo com dados registrados.</p><button id="update-cdi" class="btn primary spaced-mini">↻ Consultar CDI oficial</button><button id="update-ipca" class="btn spaced-mini">↻ Consultar IPCA oficial</button><div class="spaced-mini"><label class="field">Comparar IFIX ou Ibovespa usando CSV diário (data;valor)<select id="index-kind" class="input"><option value="IFIX">IFIX</option><option value="IBOVESPA">Ibovespa</option></select></label><label class="btn spaced-mini">⇧ Importar série do índice <input id="index-csv" type="file" class="hide" accept=".csv,.txt"/></label></div><div class="section-note">Ibovespa: ${p.extraComparators?.IBOVESPA?fmt(p.extraComparators.IBOVESPA.cumulativePercent,2)+'%':'sem série'} · IFIX: ${p.extraComparators?.IFIX?fmt(p.extraComparators.IFIX.cumulativePercent,2)+'%':'sem série'} · IPCA acumulado nos meses documentados: ${p.extraComparators?.IPCA?fmt(p.extraComparators.IPCA.cumulativePercent,2)+'%':'sem série'}. Dados de índices em CSV são fornecidos pelo usuário e não passam por validação oficial automática.</div><div class="section-note">CDI é uma taxa diária; comparar corretamente requer mesmo intervalo, fluxo de caixa ajustado e cotações completas. Outros índices (IFIX, Ibovespa, IPCA) aguardam fontes e séries com direitos de uso.</div></section></div>
<section class="card spaced"><h2>Como ter evolução desde a primeira compra?</h2><p class="subheading">Importe o histórico de negociações da B3 (datas, quantidades e preços) em Importar B3. Depois importe preços históricos cobrindo todo o período em Preços. Um PDF apenas com a posição atual não permite reconstruir o passado.</p><p class="small muted">Observações históricas: ${fmt(S.quoteHistoryStats?.observations||0,0)}. Taxas CDI diárias: ${fmt(S.benchmarkDays||0,0)}.</p></section>`;
}
function calendar(){const events=[...(S.events||[])].sort((a,b)=>a.date.localeCompare(b.date));return `${head('AGENDA','Calendário de proventos','Datas e valores cadastrados pelo usuário, separados em confirmados e estimados.')}
<div class="grid-2"><section class="card"><h2>Próximos eventos</h2>${events.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Ticker</th><th>Valor / cota</th><th>Valor esperado*</th><th>Status</th><th></th></tr></thead><tbody>${events.map(e=>`<tr><td>${dateBR(e.date)}</td><td>${esc(e.ticker)}</td><td>${BRL(e.perShare)}</td><td>${(()=>{const f=S.futureEvents.find(z=>z.id===e.id);return f?.amount===null||f?.amount===undefined?'—':BRL(f.amount);})()}</td><td><span class="badge ${e.kind==='ESTIMADO'?'moderate':''}">${e.kind==='ESTIMADO'?'Estimado':'Informado como confirmado'}</span></td><td><button class="btn smol danger" data-remove-event="${esc(e.id)}">×</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhum evento cadastrado.</div>'}</section><section class="card"><h2>Registrar pagamento futuro</h2><form id="event-form"><div class="form-grid two"><label class="field">Ticker<input class="input" name="ticker" placeholder="MXRF11" required></label><label class="field">Data de pagamento<input class="input" name="date" type="date" required></label><label class="field">Data-com / data-base (opcional)<input class="input" name="recordDate" type="date"></label><label class="field">Valor por cota (R$)<input class="input" name="perShare" type="number" min="0" step="any" required></label><label class="field">Status<select class="input" name="kind"><option value="ESTIMADO">Estimado</option><option value="CONFIRMADO">Confirmado por fonte</option></select></label><label class="field wide">Fonte<input class="input" name="source" placeholder="Comunicado do fundo..." required></label><label class="field wide">Observação<input class="input" name="note"></label></div><div class="form-actions"><button class="btn primary">Salvar data</button></div></form><div class="section-note">Datas e valores são fornecidos por você; não são conferidos automaticamente. O valor esperado só será calculado quando houver data-base de elegibilidade e quantidades históricas suficientes.</div></section></div>`;}
function quotes(){const rows=S.quotes||[];return `${head('VALORAÇÃO','Preços e atualização','Preços históricos da B3, valores manuais ou feed externo atrasado. Mostramos a data e a origem, nunca prometemos tempo real.')}
<section class="card spaced"><div class="card-header"><h2>Atualização opcional de preços • brapi</h2><span class="pill">Atraso ~30 min no plano gratuito</span></div><div class="form-grid two"><label class="field">Sua chave brapi (somente nesta sessão, não salva)<input class="input" type="password" id="market-api-key" autocomplete="off" placeholder="Chave da sua conta no provedor" value="${esc(S.marketKey)}"></label><div class="field"><span>Atualizar carteira e desejos</span><button class="btn primary" id="brapi-refresh">↻ Atualizar preços consultando provedor</button></div></div><label class="toggle spaced-mini"><input id="market-autorefresh" type="checkbox" ${S.marketAuto?'checked':''}> Atualizar automaticamente a cada 30 minutos enquanto esta janela estiver aberta</label><p class="section-note">Fonte: brapi.dev. O plano gratuito pode ter aproximadamente 30 minutos de atraso e limitar tickers e consultas. Sua chave é enviada somente ao provedor durante a consulta, não é persistida no banco. Verifique as condições de uso comercial. Atualização não significa tempo real.</p><div id="feed-status" class="small muted">${esc(S.settings?.lastProviderRefresh?.at?'Última atualização: '+S.settings.lastProviderRefresh.at:'Nenhuma atualização via provedor nesta instalação.')}</div></section>
<div class="grid-2"><section class="card"><h2>Preços informados</h2>${rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Ticker</th><th>Preço</th><th>Data</th><th>Origem</th><th></th></tr></thead><tbody>${rows.map(q=>`<tr><td>${esc(q.ticker)}</td><td>${BRL(q.price)}</td><td>${dateBR(q.date)}</td><td><span class="small muted">${esc(q.source||"manual")}</span></td><td><button class="btn smol danger" data-remove-quote="${esc(q.ticker)}">Excluir</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhum preço cadastrado.</div>'}</section><section class="card"><h2>Registrar preço de referência</h2><p class="lead">Use dados que você verificou. O valor de mercado estimado da carteira será calculado com o preço informado nesta tela.</p><form id="quote-form"><div class="form-grid two"><label class="field">Ticker<input class="input" name="ticker" placeholder="VGIR11" required></label><label class="field">Preço observado (R$)<input class="input" name="price" type="number" step="any" min="0.001" required></label><label class="field wide">Data da observação<input class="input" name="date" type="date" value="${today()}" required></label></div><div class="form-actions"><button class="btn primary">Salvar preço</button></div></form><div class="section-note">Valor parcial com preços cadastrados: ${BRL(S.analytics.marketValue)} (${S.analytics.covered}/${S.analytics.totalPositions} posições cobertas). ${S.analytics.marketValueComplete?'Todos os ativos possuem preço de referência.':'O total não representa a carteira inteira.'}</div></section></div>
<section class="card spaced"><div class="card-header"><h2>Cotações oficiais de fechamento B3</h2><span class="pill">COTAHIST · Dados históricos</span></div><p class="lead">Use o botão de atualização para baixar um dos arquivos diários públicos da B3, ou selecione um arquivo COTAHIST ZIP/TXT exportado. Importaremos somente os tickers da carteira e da lista de desejos. O fechamento não é ajustado por eventos corporativos.</p><div class="row-actions"><button class="btn primary" id="b3-update">↻ Buscar último fechamento disponível</button><label class="btn">⇧ Importar COTAHIST ZIP/TXT<input class="hide" type="file" id="b3-price-file" accept=".zip,.txt"/></label></div><p class="small muted" id="market-feedback">Última atualização local: ${esc(S.settings?.lastB3QuoteImport?.at?.slice(0,16)||'não realizada')}. A consulta depende do servidor público da B3 estar disponível.</p><div id="market-preview"></div></section>`;}
function income(){const rows=S.transactions.filter(x=>['DIVIDEND','JCP'].includes(x.type)).sort((a,b)=>b.date.localeCompare(a.date));return `${head('RENDA PASSIVA','Meus proventos','Rendimentos efetivamente lançados, agrupados por mês e por ticker.')}
<div class="metrics">${card('Total registrado',BRL(S.summary.dividends),'Proventos históricos')}${card('Últimos 12 meses',BRL(rows.filter(x=>x.date>=new Date(Date.now()-365*86400000).toISOString().slice(0,10)).reduce((s,x)=>s+x.amount,0)),'Período móvel')}${card('Ativos pagadores',Object.keys(Object.fromEntries(S.analytics.dividendsByTicker)).length,'Com histórico')}${card('Meses registrados',S.analytics.dividendsByMonth.length,'Com proventos')}</div><div class="grid-2"><section class="card"><h2>Por mês</h2>${chart(S.analytics.dividendsByMonth.slice(-18))}<div class="table-wrap"><table class="table"><thead><tr><th>Mês</th><th>Recebido</th></tr></thead><tbody>${S.analytics.dividendsByMonth.slice().reverse().map(([m,v])=>`<tr><td>${esc(m)}</td><td>${BRL(v)}</td></tr>`).join('')}</tbody></table></div></section><section class="card"><h2>Por ativo</h2>${S.analytics.dividendsByTicker.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Ticker</th><th>Total</th></tr></thead><tbody>${S.analytics.dividendsByTicker.map(([t,v])=>`<tr><td>${esc(t)}</td><td>${BRL(v)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhum dividendo registrado.</div>'}</section></div><section class="card spaced"><h2>Pagamentos individuais</h2>${txTable(rows,false)}</section>`;}
function ai(){return `${head('INTELIGÊNCIA FINANCEIRA','Metrics AI','Modelo local ou chave própria. Contexto e documentos são enviados apenas com autorização.',`<button class="btn danger" id="clear-chat">Limpar chat</button>`)}
<div class="ai-layout"><section class="card chat-box"><div class="card-header"><h2>Seu analista de dados</h2><span class="pill">${S.ai.provider==='ollama'?'Ollama local':S.ai.provider==='openai'?'API externa':'Resumo calculado'}</span></div><div class="chat-messages" id="chat-messages">${S.messages.length?S.messages.map(m=>`<div class="message ${m.role==='user'?'user':'assistant'}"><div class="message-label">${m.role==='user'?'VOCÊ':'METRICS AI'}</div>${esc(m.content)}</div>`).join(''):'<div class="empty" style="margin:auto"><div class="emoji">✧</div><h2>O que vamos analisar?</h2><p>Analise sua carteira, documentos importados e possíveis novos investimentos.</p><p class="small">Não há busca autônoma na web nesta versão.</p></div>'}</div><form id="chat-form" class="chat-compose"><textarea class="input" id="chat-question" required rows="3" placeholder="Compare os riscos dos FIIs que tenho e dos que quero comprar."></textarea><button class="btn primary" ${S.busy?'disabled':''}>${S.busy?'Analisando…':'Enviar ↗'}</button></form></section><div class="ai-side"><section class="card"><h2>Configuração híbrida</h2><label class="field spaced-mini">Provedor<select class="input" id="ai-provider"><option value="insights" ${opt(S.ai.provider,'insights')}>Resumo local, sem modelo (grátis)</option><option value="ollama" ${opt(S.ai.provider,'ollama')}>Ollama local</option><option value="openai" ${opt(S.ai.provider,'openai')}>Chave externa (OpenAI)</option></select></label><label class="field spaced-mini">Modelo<input class="input" id="ai-model" value="${esc(S.ai.model)}" placeholder="qwen2.5:3b"></label><label class="field spaced-mini ${S.ai.provider==='openai'?'':'hide'}" id="ai-key-field">Chave de API, não armazenada<input class="input" id="ai-key" type="password" autocomplete="off" value="${esc(S.ai.key)}"></label><label class="toggle spaced-mini"><input type="checkbox" id="ai-context" ${S.ai.context?'checked':''}>Incluir carteira, desejos, preços manuais e documentos relacionados</label><div class="section-note">No modo externo, dados autorizados são enviados ao provedor. O resumo local não utiliza um modelo de linguagem. Textos recuperados dos documentos são dados não confiáveis. Sem consulta direta à B3.</div><button class="btn spaced-mini" id="test-ollama">Testar Ollama</button><p class="small muted" id="ai-status"></p></section><section class="card"><h2>Dados verificáveis da carteira</h2><p class="small muted">Calculados diretamente dos lançamentos. Se houver posições da B3 importadas, elas aparecem separadas do preço médio.</p><p><b>Saldo investido pelo custo:</b> ${BRL(S.facts?.summary?.holdingCost??0)}</p><p><b>Recebimentos informados:</b> ${BRL(S.facts?.summary?.receivedIncome??0)}</p><p><b>Ativos monitorados:</b> ${S.facts?.watchlist?.length??0}</p><p class="small muted">Não é retorno futuro nem cotação ao vivo.</p>${chart((S.facts?.monthlyIncome||[]).map(x=>[x.month,x.amount]).slice(-7))}</section><section class="card"><h2>Sugestões</h2>${['Quais FIIs estão na minha carteira e quais quero comprar?','Resuma o último documento importado, indicando o que ainda falta verificar.','Como a concentração por ticker mudaria se eu comprasse ativos da lista de desejos?'].map(q=>`<div class="prompt-suggestion" data-question="${esc(q)}">${esc(q)}</div>`).join('')}</section></div></div>`;}
function stageRow(stage,i){return `<div class="phase-row" data-phase="${i}"><span class="phase-count">${i+1}</span><label class="field">Meses<input class="input phase-months" type="number" min="1" max="600" value="${stage.months}" required></label><label class="field">R$ / mês<input class="input phase-amount" type="number" step="any" min="0" value="${stage.amount}" required></label><button class="btn smol danger" type="button" data-del-phase="${i}" ${S.stages.length===1?'disabled':''}>×</button></div>`;}
function simulator(){return `${head('PLANEJAMENTO','Simulador flexível','Aportes em fases, dividendos reinvestidos e evolução hipotética de longo prazo.')}
<div class="grid-2"><section class="card"><h2>Dados do ativo</h2><form id="sim-form"><div class="form-grid two"><label class="field">Preço por cota (R$)<input class="input" name="price" type="number" step="any" min="0.001" value="9.58" required></label><label class="field">Dividendo por cota (R$)<input class="input" name="dividend" type="number" step="any" min="0" value="0.13" required></label><label class="field">Reinvestimento (%)<input class="input" name="reinvestPercent" type="number" step="any" min="0" max="100" value="100" required></label><label class="field">Inflação hipotética (% ao ano)<input class="input" name="inflationAnnual" type="number" step="any" value="4"></label><label class="field">Variação do preço (% ao ano)<input class="input" name="priceGrowthAnnual" type="number" step="any" value="0"></label><label class="field">Variação do dividendo (% ao ano)<input class="input" name="dividendGrowthAnnual" type="number" step="any" value="0"></label></div><h2 class="spaced-mini">Etapas do investimento</h2><div id="phase-rows">${S.stages.map(stageRow).join('')}</div><button class="btn" id="add-phase" type="button">+ Adicionar fase</button><div class="form-actions"><button class="btn primary" type="submit">Calcular cenário</button></div></form><div class="section-note">Hipóteses ilustrativas. As projeções não preveem preços ou dividendos. Considera cotas inteiras, dividendos no início do mês e aportes no fim.</div></section><section class="card"><div class="card-header"><h2>Resultado projetado</h2><span class="pill">Motor matemático local</span></div><div id="sim-result">${S.lastSimulation?simulationResult(S.lastSimulation):'<div class="empty">Preencha os valores e clique em calcular.</div>'}</div></section></div>`;}
function simulationResult(r){const last=r.last;if(!last)return '<div class="empty">Sem períodos.</div>';const vals=r.months.filter(x=>x.month%12===0||x.month===r.months.length);return `<div class="grid-half"><div class="summary-chip"><div class="small muted">Patrimônio hipotético</div><div class="value">${BRL(last.holdingsValue)}</div></div><div class="summary-chip"><div class="small muted">Aportes</div><div class="value">${BRL(last.deposited)}</div></div><div class="summary-chip"><div class="small muted">Dividendos gerados</div><div class="value positive">${BRL(last.received)}</div></div><div class="summary-chip"><div class="small muted">Renda mensal estimada</div><div class="value blue">${BRL(last.incomeNextMonth)}</div></div></div><div class="section-title">Evolução anual do patrimônio</div>${chart(vals.map(v=>[v.month+'m',v.holdingsValue]))}<div class="section-note">${fmt(last.shares,6)} cotas · ${BRL(last.cash)} em caixa · ${BRL(last.withdrawn)} em dividendos sacados · Patrimônio corrigido pela inflação simulada: ${BRL(last.realValue)}.</div><div class="form-actions"><button id="download-sim" class="btn">↓ Exportar simulação CSV</button></div>`;}
function multiAssetRow(a,i){return `<div class="multi-asset-row"><label class="field">Ticker<input class="input asset-ticker" value="${esc(a.ticker)}" maxlength="24" required></label><label class="field">Preço R$<input class="input asset-price" type="number" min="0.0001" step="any" value="${a.price}" required></label><label class="field">Dividendo R$<input class="input asset-dividend" type="number" min="0" step="any" value="${a.dividend}" required></label><label class="field">Peso %<input class="input asset-weight" type="number" min="0" max="100" step="any" value="${a.weight}" required></label><button type="button" class="btn smol danger" data-remove-multi="${i}" aria-label="Remover ativo">×</button></div>`;}
function multiSimulator(){return `${head('CENÁRIOS DE CARTEIRA','Simular vários ativos','Compare uma carteira diversificada com compras de cotas inteiras e saldos individualizados.')}
<div class="grid-2"><section class="card"><h2>Ativos da simulação</h2><div class="section-note">Preços e dividendos são hipóteses editáveis, não cotações de mercado.</div><form id="multi-form"><div id="multi-assets">${S.multiAssets.map(multiAssetRow).join('')}</div><button class="btn" type="button" id="add-multi">+ Adicionar ativo</button><h2 class="spaced-mini">Fases de aporte (compartilhadas com simulador simples)</h2><div id="multi-phases">${S.stages.map(stageRow).join('')}</div><button class="btn" type="button" id="add-multi-stage">+ Nova fase</button><div class="form-grid two spaced-mini"><label class="field">Dividendos reinvestidos (%)<input class="input" name="reinvestPercent" type="number" value="100" min="0" max="100" step="any"></label><label class="field">Inflação anual hipotética (%)<input class="input" name="inflationAnnual" type="number" value="4" step="any"></label></div><div class="form-actions"><button type="submit" class="btn primary">Simular carteira</button></div></form></section><section class="card"><div class="card-header"><h2>Resultado conjunto</h2><span class="pill">Até 12 ativos</span></div><div id="multi-results">${S.lastMulti?multiResult(S.lastMulti):'<div class="empty">Configure os pesos dos ativos (somando 100%) e simule.</div>'}</div></section></div>`;}
function multiResult(r){const l=r.last;if(!l)return '<div class="empty">Sem resultado.</div>';const years=r.months.filter(x=>x.month%12===0||x.month===r.months.length);return `<div class="grid-half"><div class="summary-chip"><span class="muted small">Patrimônio hipotético</span><div class="value">${BRL(l.holdingsValue)}</div></div><div class="summary-chip"><span class="muted small">Total aportado</span><div class="value">${BRL(l.deposited)}</div></div><div class="summary-chip"><span class="muted small">Dividendos gerados</span><div class="value positive">${BRL(l.received)}</div></div><div class="summary-chip"><span class="muted small">Renda mensal hipotética</span><div class="value blue">${BRL(l.incomeNextMonth)}</div></div></div><h2 class="spaced-mini">Patrimônio no tempo</h2>${chart(years.map(x=>[x.month+'m',x.holdingsValue]))}<h2 class="spaced-mini">Por ativo no último mês</h2><div class="table-wrap"><table class="table"><thead><tr><th>Ativo</th><th>Cotas</th><th>Patrimônio</th><th>Dividendo/mês</th></tr></thead><tbody>${l.holdings.map(h=>`<tr><td>${esc(h.ticker)}</td><td>${fmt(h.shares,0)}</td><td>${BRL(h.marketValue+h.cash)}</td><td>${BRL(h.incomeNextMonth)}</td></tr>`).join('')}</tbody></table></div><div class="section-note">Saldo em caixa ${BRL(l.cash)}; dividendos sacados ${BRL(l.withdrawn)}; valor corrigido pela inflação hipotética ${BRL(l.realValue)}. Projeção não prevê desempenho futuro.</div><button type="button" id="download-multi" class="btn spaced-mini">↓ Exportar CSV</button>`;}
function bindMulti(){const sync=()=>{S.multiAssets=$$('.multi-asset-row').map(r=>({ticker:$('.asset-ticker',r).value,price:Number($('.asset-price',r).value),dividend:Number($('.asset-dividend',r).value),weight:Number($('.asset-weight',r).value)}));S.stages=$$('#multi-phases .phase-row').map(r=>({months:Number($('.phase-months',r).value),amount:Number($('.phase-amount',r).value)}));};
 $('#add-multi').onclick=()=>{sync();if(S.multiAssets.length===12)return toast('Limite de 12 ativos.',true);S.multiAssets.push({ticker:'',price:10,dividend:.1,weight:0});render();};
 $$('[data-remove-multi]').forEach(b=>b.onclick=()=>{sync();if(S.multiAssets.length===1)return toast('Mantenha pelo menos um ativo.',true);S.multiAssets.splice(Number(b.dataset.removeMulti),1);render();});
 $('#add-multi-stage').onclick=()=>{sync();if(S.stages.length>=30)return toast('Limite de 30 fases.',true);S.stages.push({months:12,amount:400});render();};
 $$('#multi-phases [data-del-phase]').forEach(b=>b.onclick=()=>{sync();if(S.stages.length<2)return;S.stages.splice(Number(b.dataset.delPhase),1);render();});
 $('#multi-form').onsubmit=async e=>{e.preventDefault();sync();try{const result=await api('/api/simulate/portfolio',{method:'POST',data:{...formValue(e.currentTarget),assets:S.multiAssets,phases:S.stages}});S.lastMulti=result;$('#multi-results').innerHTML=multiResult(result);$('#download-multi').onclick=()=>download('metrics-carteira-futura.csv',csv([['mes','fase','aportes','dividendos','sacados','patrimonio','renda_mensal'],...result.months.map(x=>[x.month,x.phase,x.deposited,x.received,x.withdrawn,x.holdingsValue,x.incomeNextMonth])]),'text/csv');}catch(err){toast(err.message,true);}};
 if(S.lastMulti&&$('#download-multi'))$('#download-multi').onclick=()=>download('metrics-carteira-futura.csv',csv([['mes','patrimonio','renda_mensal'],...S.lastMulti.months.map(x=>[x.month,x.holdingsValue,x.incomeNextMonth])]),'text/csv');}
function imports(){return `${head('ARQUIVOS DA B3','Importador de carteira','Importe XLSX/CSV ou PDF da B3. O extrato PDF de posições será salvo como posição declarada, sem criar compras falsas.')}
<div class="grid-2"><section class="card"><h2>Enviar arquivo</h2><p class="lead">Selecione um relatório da B3 em Excel (.xlsx), CSV ou PDF. Verificamos colunas conhecidas e apresentamos uma prévia. Não gravamos nada sem sua confirmação.</p><div class="upload"><div class="emoji">⇧</div><b>XLSX, CSV, TSV, PDF ou TXT</b><input class="input" id="upload-file" type="file" accept=".xlsx,.csv,.tsv,.pdf,.txt"/><div class="small muted">Até 12 MB. PDFs pesquisáveis: documento ou fotografia das posições, com revisão antes de importar.</div></div><div class="spaced-mini"><button class="btn" id="example-csv">↓ Baixar modelo CSV</button></div><div class="section-note">Os arquivos da B3 variam de layout. Linhas desconhecidas são sinalizadas, não inventadas. Para carteira antiga incompleta, registre o saldo histórico de forma conferida antes de importar vendas.</div></section><section class="card"><h2>Revisão antes de importar</h2><div id="import-result">${importPreviewHTML()}</div></section></div>${(S.snapshots||[]).length?`<section class="card spaced"><h2>Fotografias de carteira importadas</h2>${S.snapshots.map(x=>`<div class="watch-row"><div><b>${dateBR(x.asOf)} · ${x.positions.length} ativos</b><p class="small muted">${esc(x.source)} · Não são compras</p></div><button class="btn smol danger" data-remove-snapshot="${esc(x.id)}">Excluir</button></div>`).join('')}</section>`:''}<section class="card spaced"><div class="card-header"><h2>Histórico de importações</h2><span class="pill">${S.imports.length} lotes</span></div>${S.imports.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Arquivo</th><th>Data</th><th>Adicionadas</th><th>Duplicadas ignoradas</th><th></th></tr></thead><tbody>${[...S.imports].reverse().map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.date.slice(0,10))}</td><td>${x.added}</td><td>${x.duplicates}</td><td><button class="btn smol danger" data-rollback="${esc(x.id)}">Desfazer lote</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhum arquivo importado.</div>'}</section>`;}
function importPreviewHTML(){const p=S.preview;if(!p)return '<div class="empty">Escolha um arquivo para ver o que foi reconhecido.</div>';if(p.kind==='positions')return `<div class="summary-chip"><h2>Extrato de posição: ${p.positions.length} ativos detectados</h2><p class="small muted">Leitor: ${esc(p.reader)} · Páginas: ${esc(p.pages??'não determinado')}. A importação NÃO cria compras nem preço médio fiscal.</p>${p.warnings.map(w=>`<p class="small muted">⚠ ${esc(w)}</p>`).join('')}</div><form id="save-position-snapshot"><label class="field">Data-base do extrato (obrigatória)<input class="input" type="date" id="snapshot-date" value="${esc(p.asOf||'')}" required></label><div class="table-wrap preview-table"><table class="table"><thead><tr><th>Ativo identificado</th><th>Quantidade (confira no PDF)</th><th>Preço de referência</th><th>Conferência</th></tr></thead><tbody>${p.positions.slice(0,300).map((x,i)=>`<tr><td>${esc(x.ticker)}</td><td><input class="input snapshot-quantity" type="number" min="0.000001" step="any" required data-index="${i}" value="${x.quantity}"></td><td>${x.referencePrice===null?'Não identificado':BRL(x.referencePrice)}</td><td>${esc(x.confidence==='inferido_por_valores'?'Valores cruzados':'Revisar')}</td></tr>`).join('')}</tbody></table></div><label class="toggle spaced-mini"><input type="checkbox" id="snapshot-reviewed" required> Comparei todas as quantidades com meu PDF. Estou importando posições, não compras.</label><div class="form-actions"><button class="btn primary">Salvar fotografia da carteira</button></div></form><form id="save-upload-doc" class="spaced-mini"><label class="field">Relacionar PDF a ticker (opcional)<input class="input" name="ticker" placeholder="MXRF11"></label><label class="field">Data-base para análise do documento<input class="input" name="referenceDate" type="date" value="${esc(p.asOf||'')}"></label><button class="btn">Guardar também o texto na memória documental da IA</button></form><details class="spaced-mini"><summary>Mostrar texto extraído</summary><pre class="doc-preview">${esc(p.preview)}</pre></details>`;if(p.kind==='document')return `<div class="summary-chip"><h2>Documento: ${esc(p.title)}</h2><p class="small muted">${p.chars} caracteres de texto extraídos.</p><pre class="doc-preview">${esc(p.preview)}</pre><form id="save-upload-doc"><label class="field">Ticker relacionado (opcional)<input class="input" name="ticker" placeholder="VGIR11"></label><label class="field spaced-mini">Data-base (opcional)<input class="input" name="referenceDate" type="date"></label><div class="form-actions"><button class="btn primary">Guardar para a IA</button></div></form></div>`;return `<div class="summary-chip"><h2>${p.operations.length} operações identificadas</h2><p class="small muted">${p.unrecognizedTotal||0} linhas não reconhecidas. ${(p.sheets||[]).map(s=>esc(s.sheet)+' '+esc(s.status)).join(' · ')}</p><p class="small muted">${esc(p.reason||'Confira as taxas com as notas de corretagem e os negócios no extrato original.')}</p></div><div class="table-wrap preview-table"><table class="table"><thead><tr><th>Data</th><th>Ativo</th><th>Tipo</th><th>Quantidade / valor</th></tr></thead><tbody>${p.operations.slice(0,80).map(t=>`<tr><td>${dateBR(t.date)}</td><td>${esc(t.ticker)}</td><td>${t.type}</td><td>${['DIVIDEND','JCP','AMORTIZATION'].includes(t.type)?BRL(t.amount):fmt(t.quantity,4)+' × '+BRL(t.price)}</td></tr>`).join('')}</tbody></table></div>${p.unrecognizedTotal?`<div class="section-note">Linhas ignoradas (amostra): ${esc((p.unrecognized||[]).slice(0,12).map(x=>typeof x==='string'?x:`linha ${x.line}: ${x.reason}`).join(', '))}. Confira o arquivo original para dados não importados.</div>`:''}<label class="toggle spaced-mini"><input type="checkbox" id="keep-duplicate-rows"> Importar também operações idênticas já cadastradas (use apenas quando confirmar que são negócios diferentes)</label><div class="form-actions"><button class="btn primary" id="commit-import" ${!p.operations.length?'disabled':''}>Importar lançamentos reconhecidos</button></div>`;}
function documents(){return `${head('BASE DE CONHECIMENTO','Meus documentos','Relatórios fornecidos pelo usuário. A IA lê trechos relevantes quando autorizada.')}
<div class="grid-2"><section class="card"><div class="card-header"><h2>Documentos importados</h2><span class="pill">${S.documents.length}</span></div>${S.documents.length?S.documents.map(d=>`<div class="watch-row"><div><b>${esc(d.title)}</b><p class="small muted">${esc(d.ticker||'Sem ticker')} · ${esc(d.referenceDate||'Sem data-base')} · ${fmt(d.chars,0)} caracteres</p></div><div class="inline-buttons"><button class="btn smol" data-read-doc="${esc(d.id)}">Ler</button><button class="btn smol" data-analyze-doc="${esc(d.id)}">IA</button><button class="btn smol danger" data-remove-doc="${esc(d.id)}">Excluir</button></div></div>`).join(''):'<div class="empty">Nenhum documento. Importe um PDF/TXT na seção Importar B3.</div>'}</section><section class="card"><h2>Como a IA consulta os documentos</h2><p class="lead">O texto é armazenado localmente e pesquisado quando uma pergunta menciona o ticker ou assunto. Somente os trechos selecionados entram no contexto da IA, se você autorizar.</p><div class="section-note">Documentos fornecidos pelo usuário não são automaticamente oficiais. A IA deve diferenciar informações encontradas, interpretações e hipóteses. Não existem cotações em tempo real nem pesquisa web automática.</div><button class="btn primary spaced-mini" data-nav="import">+ Importar documento</button></section></div><section class="card spaced hide" id="doc-reading"><h2 id="doc-title"></h2><pre id="doc-text" class="doc-preview"></pre></section>`;}
function tax(){const years=[...new Set(S.transactions.map(t=>t.date.slice(0,4)))].sort().reverse(),year=years[0]||today().slice(0,4);return `${head('EXPORTAÇÕES','Relatórios e IR','Arquivos auxiliares para conferência. Não são declaração pronta para a Receita Federal.')}
<div class="metrics">${card('Operações',S.transactions.length,'Compras, vendas e proventos')}${card('Proventos informados',BRL(S.summary.dividends),'Requer verificação fiscal')}${card('Vendas realizadas',BRL(S.summary.realized),'Não é imposto calculado')}${card('Anos com histórico',years.length,'Apenas dados lançados')}</div><div class="grid-2"><section class="card"><h2>Exportar relatórios</h2><label class="field spaced-mini">Ano-calendário<select class="input" id="tax-year">${years.length?years.map(y=>`<option value="${y}">${y}</option>`).join(''):`<option value="${year}">${year}</option>`}</select></label><div class="stack-buttons"><button class="btn primary" id="export-year">↓ Relatório anual CSV</button><button class="btn" id="export-transactions">↓ Histórico completo CSV</button><button class="btn" id="export-income">↓ Proventos por mês CSV</button><button class="btn" id="export-positions">↓ Posições atuais CSV</button><button class="btn" id="export-xlsx">↓ Relatório Excel XLSX</button><button class="btn" id="print-report">⎙ Imprimir ou salvar PDF</button><button class="btn" id="calculate-ledger">▤ Calcular resultados fiscais por mês</button><button class="btn" id="export-ledger">↓ Vendas por ativo CSV</button></div></section><section class="card"><h2>Atenção ao Imposto de Renda</h2><p class="lead">O Metrics organiza informações inseridas pelo usuário, mas não apura automaticamente DARF, prejuízos compensáveis, eventos corporativos ou todas as regras por categoria e exercício.</p><div class="section-note">O valor realmente declarável depende de histórico de aquisição completo, notas de corretagem, IRRF, compensações e informes oficiais. O Metrics sinaliza a incompletude em vez de inventar campos fiscais. <a href="https://www.gov.br/receitafederal/pt-br/assuntos/meu-imposto-de-renda/pagamento/renda-variavel/manual" target="_blank" rel="noopener noreferrer">Manual oficial ReVar, Receita Federal</a>. Revise dados e regras do ano-calendário.</div></section></div><section class="card spaced"><div class="card-header"><h2>Conciliação de vendas por mês</h2><span class="pill">Base de cálculo, NÃO DARF</span></div><div id="tax-detail">${taxDetail()}</div></section>`;}
function taxDetail(){const d=S.taxLedger;if(!d)return '<div class="empty">Escolha o ano e clique em calcular resultados. Classifique os tickers em Analisar antes de usar este relatório.</div>';return `<div class="metrics">${card('Volume vendido',BRL(d.totals.sold),'Registros presentes')}${card('Resultado líquido das vendas',BRL(d.totals.result),'Antes de tributos')}${card('Proventos cadastrados',BRL(d.totals.proceeds),'Classificação fiscal pendente')}</div><div class="table-wrap"><table class="table"><thead><tr><th>Mês</th><th>Classe</th><th>Vendas</th><th>Ganhos</th><th>Prejuízos</th><th>Líquido</th></tr></thead><tbody>${d.monthly.map(x=>`<tr><td>${esc(x.month)}</td><td>${esc(x.kind)}</td><td>${BRL(x.volume)}</td><td>${BRL(x.gain)}</td><td>${BRL(x.loss)}</td><td>${BRL(x.netResult)}</td></tr>`).join('')}</tbody></table></div><div class="section-note"><h3>Checklist de documentação fiscal</h3>${(d.fiscalChecklist||[]).map(x=>`<p class="small"><b>${esc(x.item)}:</b> ${esc(x.status)}</p>`).join('')}</div><div class="section-note"><b>Estado fiscal: ${esc(d.readiness)}</b><p>${d.annualStatementCompared?'Conferência com posição de 31/12: '+(d.annualDiscrepancies?.length?'DIVERGÊNCIA em '+d.annualDiscrepancies.map(x=>esc(x.ticker)).join(', '):'Quantidades informadas conciliadas para os tickers presentes no extrato. Consulte também ativos ausentes.'):'Sem extrato de posição de 31/12 para conciliar.'}</p>${d.issues.map(x=>'⚠ '+esc(x)).join('<hr/>')}</div>${d.yearEndPositions?.length?`<h3>Posições calculadas em 31/12 do ano</h3><div class="table-wrap"><table class="table"><thead><tr><th>Ativo</th><th>Cotas</th><th>Custo dos lançamentos</th></tr></thead><tbody>${d.yearEndPositions.map(p=>`<tr><td>${esc(p.ticker)}</td><td>${fmt(p.quantity,6)}</td><td>${BRL(p.cost)}</td></tr>`).join('')}</tbody></table></div>`:''}<details class="spaced-mini"><summary>Documentos a conferir antes de declarar</summary>${(d.documentChecklist||[]).map(x=>`<p class="small muted">☐ ${esc(x)}</p>`).join('')}</details><p class="small muted">Referências: Receita Federal, regras de operações em bolsa e FIIs. Conferência profissional recomendada.</p>`;}
function settings(){return `${head('PREFERÊNCIAS','Configurações','Backups, privacidade, dados locais e estado das integrações.')}
<div class="settings-grid"><section class="card"><h2>Armazenamento local</h2><div class="section-note"><b>Diretório:</b> <span class="code">${esc(S.dataLocation||'')}</span><br><b>Banco:</b> SQLite local<br><b>Criptografia em repouso:</b> ${S.encrypted?'Ativa via senha de inicialização':'Desativada por padrão'}</div><div class="stack-buttons"><button class="btn primary" id="backup">↓ Backup criptografado com senha</button><label class="btn" for="restore-file">↑ Restaurar backup JSON</label><input type="file" id="restore-file" accept=".json,application/json" class="hide"></div><div class="section-note">O backup gerado nesta versão é protegido com senha. Guarde a senha em local seguro. Backups antigos em JSON continuam legíveis. Restaurar substitui todos os dados. Para proteger o banco com senha, siga o README antes de inserir dados pessoais.</div></section><section class="card"><h2>Fontes e limitações</h2><div class="watch-row"><b>IA local</b><span class="badge">Ollama opcional</span></div><div class="watch-row"><b>IA externa</b><span class="badge">Chave do usuário</span></div><div class="watch-row"><b>Fechamento B3 COTAHIST</b><span class="badge">Sob demanda e offline</span></div><div class="watch-row"><b>CSV / XLSX</b><span class="badge">Prévia e revisão</span></div><div class="watch-row"><b>PDF com texto</b><span class="badge">Leitura local</span></div><div class="section-note">O aplicativo não envia ordens, não solicita senhas bancárias e não fornece previsões de mercado garantidas.</div></section></div>`;}
const pages={dashboard,ai,wallet,watch,assets,quotes,performance,radar,income,calendar,sim:simulator,multi:multiSimulator,import:imports,docs:documents,tax,settings,portfolios:portfolioPage,extensions:extensionPage};
function download(name,contents,type='text/plain;charset=utf-8'){const blob=new Blob([contents],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadBase64(name,b64,type){const binary=atob(b64),arr=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)arr[i]=binary.charCodeAt(i);download(name,arr,type);}
function csv(rows){return '\uFEFF'+rows.map(row=>row.map(value=>'"'+String(value??'').replaceAll('"','""')+'"').join(';')).join('\r\n');}
function formValue(form){return Object.fromEntries(new FormData(form).entries());}
function go(page){S.page=page;render();scrollTo(0,0);}
function render(){ $('#app').innerHTML=shell();$('#theme').onclick=()=>{S.theme=S.theme==='dark'?'light':'dark';try{localStorage.setItem('metrics-theme',S.theme);}catch{}render();};$$('[data-nav]').forEach(el=>el.onclick=()=>go(el.dataset.nav));bindPage();bindPortfolioControls();if(S.page==='portfolios')bindPortfolioPage();if(S.page==='extensions')bindExtensionsPage();if(S.page==='classes')bindClasses();if(S.page==='notices')bindNotices();if(S.page==='sources'){bindSourcesV12();bindSourcesV13();}}
function onActions(){
 $$('[data-remove-watch]').forEach(el=>el.onclick=async()=>{if(!confirm('Remover ativo desejado?'))return;try{await api('/api/watchlist/'+el.dataset.removeWatch,{method:'DELETE'});await update();render();}catch(e){toast(e.message,true);}});
 $$('[data-edit-watch]').forEach(el=>el.onclick=async()=>{const w=S.watchlist.find(w=>w.id===el.dataset.editWatch);const target=prompt(`Novo preço de interesse para ${w.ticker} (deixe vazio para nenhum):`,w.target??'');if(target===null)return;const budget=prompt('Valor que você planeja aplicar:',w.budget??'');if(budget===null)return;const notes=prompt('Motivo para acompanhar:',w.notes??'');if(notes===null)return;try{await api('/api/watchlist/'+w.id,{method:'PUT',data:{target,budget,notes}});await update();render();toast('Lista atualizada.');}catch(e){toast(e.message,true);}});
}
function bindPage(){onActions();if(S.page==='wallet'){
 $('#corporate-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/transactions',{method:'POST',data:formValue(e.currentTarget)});await update();render();toast('Evento societário registrado. Confira o preço médio.');}catch(err){toast(err.message,true);}};
 $('#tx-type').onchange=()=>{const div=['DIVIDEND','JCP','AMORTIZATION'].includes($('#tx-type').value);$$('[data-trade]').forEach(x=>x.classList.toggle('hide',div));$('#tx-dividend').classList.toggle('hide',!div);};
 $('#tx-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/transactions',{method:'POST',data:formValue(e.currentTarget)});await update();render();toast('Operação salva.');}catch(x){toast(x.message,true);}};
 $$('[data-edit-tx]').forEach(btn=>btn.onclick=()=>{S.editingTransactionId=btn.dataset.editTx;render();$('#tx-edit-panel')?.focus();$('#tx-edit-panel')?.scrollIntoView({behavior:'smooth',block:'center'});});
 $$('[data-remove-tx]').forEach(btn=>btn.onclick=async()=>{const t=S.transactions.find(x=>x.id===btn.dataset.removeTx);if(!t)return;if(!confirm(`Excluir o lançamento ${t.ticker} de ${dateBR(t.date)}? O histórico e o custo médio serão recalculados. Você poderá desfazer depois.`))return;try{await api('/api/transactions/'+encodeURIComponent(t.id),{method:'DELETE'});if(S.editingTransactionId===t.id)S.editingTransactionId=null;await update();render();toast('Lançamento excluído. Use “Desfazer última ação” para restaurá-lo.');}catch(e){toast(e.message,true);}});
 if($('#tx-history-filter'))$('#tx-history-filter').oninput=e=>{const query=e.target.value.trim().toLocaleLowerCase('pt-BR');$$('#tx-history-list tbody tr').forEach(row=>{row.hidden=!!query&&!row.innerText.toLocaleLowerCase('pt-BR').includes(query);});};
 if($('#undo-last-tx'))$('#undo-last-tx').onclick=async()=>{const a=(S.transactionAudit||[]).filter(x=>!x.undoneAt).at(-1);if(!a)return;try{await api('/api/transactions/undo',{method:'POST',data:{auditId:a.id}});S.editingTransactionId=null;await update();render();toast('Última alteração desfeita; valores recalculados.');}catch(err){toast(err.message,true);}};
 if($('#tx-edit-form')){$('#tx-edit-form').onsubmit=async e=>{e.preventDefault();try{const t=S.transactions.find(x=>x.id===S.editingTransactionId);if(!t)throw Error('Lançamento não encontrado.');await api('/api/transactions/'+encodeURIComponent(t.id),{method:'PUT',data:{...formValue(e.currentTarget),...(t.type==='AMORTIZATION'?{adjustCost:e.currentTarget.elements.adjustCost.value==='true'}:{})}});S.editingTransactionId=null;await update();render();toast('Correção salva; carteira e resultados recalculados.');}catch(err){toast(err.message,true);}};
  $('#cancel-edit-tx').onclick=$('#cancel-edit-tx-bottom').onclick=()=>{S.editingTransactionId=null;render();};}

 }if(S.page==='watch'){$('#watch-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/watchlist',{method:'POST',data:formValue(e.currentTarget)});await update();render();toast('Ativo desejado adicionado.');}catch(x){toast(x.message,true);}};}
 if(S.page==='assets'){ $('#profile-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/profiles',{method:'POST',data:formValue(e.currentTarget)});await update();render();toast('Ficha atualizada.');}catch(x){toast(x.message,true);}};$$('[data-remove-profile]').forEach(b=>b.onclick=async()=>{if(!confirm('Excluir esta ficha?'))return;await api('/api/profiles/'+b.dataset.removeProfile,{method:'DELETE'});await update();render();});}
 if(S.page==='calendar'){ $('#event-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/events',{method:'POST',data:formValue(e.currentTarget)});await update();render();toast('Evento salvo.');}catch(x){toast(x.message,true);}};$$('[data-remove-event]').forEach(b=>b.onclick=async()=>{await api('/api/events/'+b.dataset.removeEvent,{method:'DELETE'});await update();render();});}
 if(S.page==='performance'){
  const b=$('#update-cdi');b.onclick=async()=>{b.disabled=true;try{const r=await api('/api/benchmark/cdi-update',{method:'POST',data:{}});await update();render();toast(`CDI oficial: ${r.added} dias carregados.`);}catch(err){toast(err.message,true);b.disabled=false;}};
  $('#update-ipca').onclick=async()=>{const btn=$('#update-ipca');btn.disabled=true;try{const r=await api('/api/benchmark/ipca-update',{method:'POST',data:{}});await update();render();toast(`IPCA SGS 433: série atualizada com ${r.total} meses.`);}catch(err){toast(err.message,true);btn.disabled=false;}};
  $('#index-csv').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>3*1024*1024)throw Error('CSV de índice grande demais.');const kind=$('#index-kind').value;const r=await api('/api/benchmark/index-import',{method:'POST',data:{kind,name:file.name,csv:await file.text()}});await update();render();toast(`${kind}: ${r.total} observações importadas para comparação.`);}catch(err){toast(err.message,true);}};
 }
 if(S.page==='radar')bindRadar();
 if(S.page==='quotes'){
  $('#market-api-key').oninput=e=>S.marketKey=e.target.value;$('#market-autorefresh').onchange=e=>S.marketAuto=e.target.checked;$('#brapi-refresh').onclick=async()=>{if(S.marketRefreshing)return;S.marketRefreshing=true;const btn=$('#brapi-refresh');btn.disabled=true;try{const r=await api('/api/market/provider-refresh',{method:'POST',data:{key:S.marketKey}});await update();render();toast(`${r.updated} preços carregados. Cotação atrasada, veja a fonte. ${r.failures?.length?r.failures.length+' tickers sem resposta.':''}`);}catch(err){toast(err.message,true);if($('#feed-status'))$('#feed-status').textContent=err.message;}finally{S.marketRefreshing=false;if($('#brapi-refresh'))$('#brapi-refresh').disabled=false;}};
  $('#b3-update').onclick=async()=>{const btn=$('#b3-update');btn.disabled=true;$('#market-feedback').textContent='Consultando a B3...';try{const result=await api('/api/market/update',{method:'POST',data:{}});await update();render();toast(`${result.updated} preços atualizados pela B3, data-base ${dateBR(result.marketDataDate)}.`);}catch(e){$('#market-feedback').textContent=e.message;toast(e.message,true);}finally{if($('#b3-update'))$('#b3-update').disabled=false;}};
  $('#b3-price-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>24*1024*1024)throw Error('Máximo de 24MB');const data=await toBase64(file);const preview=await api('/api/market/preview',{method:'POST',data:{name:file.name,data}});S.marketPreview={...preview,name:file.name,data};$('#market-preview').innerHTML=`<div class="section-note">Encontrados ${preview.quotes.length} tickers da sua carteira/lista (de ${preview.records} registros, ${preview.historyCount||0} preços históricos). Fonte: ${esc(preview.source)}. Preços são fechamentos sem ajustes.</div><div class="table-wrap"><table class="table"><thead><tr><th>Ticker</th><th>Fechamento</th><th>Data</th></tr></thead><tbody>${preview.quotes.slice(0,60).map(q=>`<tr><td>${esc(q.ticker)}</td><td>${BRL(q.price)}</td><td>${dateBR(q.date)}</td></tr>`).join('')}</tbody></table></div><button class="btn primary spaced-mini" id="b3-confirm">Confirmar atualização de preços</button>`;$('#b3-confirm').onclick=async()=>{const result=await api('/api/market/import',{method:'POST',data:{name:file.name,data}});S.marketPreview=null;await update();render();toast(`${result.updated} preços B3 atualizados; ${result.historical?.added||0} observações históricas adicionadas.`);};}catch(err){toast(err.message,true);}};
  $('#quote-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/quotes',{method:'POST',data:formValue(e.currentTarget)});await update();render();toast('Preço de referência salvo.');}catch(x){toast(x.message,true);}};$$('[data-remove-quote]').forEach(x=>x.onclick=async()=>{await api('/api/quotes/'+x.dataset.removeQuote,{method:'DELETE'});await update();render();});}
 if(S.page==='sim')bindSimulation();if(S.page==='multi')bindMulti();if(S.page==='ai')bindAI();if(S.page==='import')bindImport();if(S.page==='docs')bindDocs();if(S.page==='tax')bindReports();if(S.page==='settings')bindSettings();}
function bindSimulation(){const sync=()=>{S.stages=$$('.phase-row').map(row=>({months:Number($('.phase-months',row).value),amount:Number($('.phase-amount',row).value)}));};
 $('#add-phase').onclick=()=>{sync();if(S.stages.length>=30){toast('Máximo de 30 fases.');return;}S.stages.push({months:12,amount:500});render();};
 $$('[data-del-phase]').forEach(b=>b.onclick=()=>{sync();S.stages.splice(Number(b.dataset.delPhase),1);render();});
 $('#sim-form').onsubmit=async e=>{e.preventDefault();sync();try{const result=await api('/api/simulate',{method:'POST',data:{...formValue(e.currentTarget),phases:S.stages}});S.lastSimulation=result;$('#sim-result').innerHTML=simulationResult(result);$('#download-sim').onclick=()=>download('metrics-simulacao.csv',csv([['mes','fase','cotas','preco','dividendo','aportes','dividendos','sacados','caixa','patrimonio','patrimonio_real','renda_mensal'],...result.months.map(x=>[x.month,x.phase,x.shares,x.price,x.dividend,x.deposited,x.received,x.withdrawn,x.cash,x.holdingsValue,x.realValue,x.incomeNextMonth])]),'text/csv');}catch(x){toast(x.message,true);}};
 if(S.lastSimulation&&$('#download-sim'))$('#download-sim').onclick=()=>download('metrics-simulacao.csv',csv([['mes','cotas','patrimonio','dividendos'],...S.lastSimulation.months.map(x=>[x.month,x.shares,x.holdingsValue,x.received])]),'text/csv');}
function bindAI(){if($('#chat-messages'))$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;
 $('#ai-provider').onchange=e=>{S.ai.provider=e.target.value;S.ai.model=S.ai.provider==='ollama'?'qwen2.5:3b':S.ai.provider==='openai'?'gpt-4.1-mini':'local';render();};
 $('#ai-model').oninput=e=>S.ai.model=e.target.value;$('#ai-context').onchange=e=>S.ai.context=e.target.checked;if($('#ai-key'))$('#ai-key').oninput=e=>S.ai.key=e.target.value;
 $('#clear-chat').onclick=async()=>{if(!confirm('Apagar histórico de conversas?'))return;await api('/api/chat/clear',{method:'POST',data:{}});S.messages=[];render();};
 $('#test-ollama').onclick=async()=>{try{const x=await api('/api/ollama/models');$('#ai-status').textContent=x.available?'Modelos: '+x.models.join(', '):'Ollama não está ativo neste computador.';}catch(x){toast(x.message,true);}};
 $$('[data-question]').forEach(x=>x.onclick=()=>{$('#chat-question').value=x.dataset.question;$('#chat-question').focus();});
 $('#chat-form').onsubmit=async e=>{e.preventDefault();if(S.busy)return;const question=$('#chat-question').value.trim();if(!question)return;S.busy=true;S.messages=[...S.messages,{role:'user',content:question}];render();try{const x=await api('/api/chat',{method:'POST',data:{provider:S.ai.provider,model:S.ai.model,key:S.ai.key,context:S.ai.context,messages:S.messages}});S.messages.push({role:'assistant',content:x.answer});}catch(err){S.messages.pop();toast(err.message,true);}finally{S.busy=false;render();}};
}
async function toBase64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});}
function bindImport(){const hook=()=>{if($('#save-upload-doc'))$('#save-upload-doc').onsubmit=async e=>{e.preventDefault();try{const p=S.preview;await api('/api/documents',{method:'POST',data:{title:p.title,text:p.text,source:'Arquivo importado',...formValue(e.currentTarget)}});S.preview=null;await update();render();toast('Documento salvo para análise com a IA.');}catch(x){toast(x.message,true);}};
 if($('#save-position-snapshot'))$('#save-position-snapshot').onsubmit=async e=>{e.preventDefault();const p=S.preview;try{
  const positions=p.positions.map((x,i)=>({...x,quantity:Number($$('.snapshot-quantity')[i].value)}));
  await api('/api/snapshots',{method:'POST',data:{asOf:$('#snapshot-date').value,source:p.name,positions}});
  S.preview=null;await update();render();toast('Posição da B3 registrada sem fabricar operações de compra.');
 }catch(err){toast(err.message,true);}};
 if($('#commit-import'))$('#commit-import').onclick=async()=>{const p=S.preview;if(p.unrecognizedTotal&&!confirm(`${p.unrecognizedTotal} linhas não serão importadas. Confirmar somente as ${p.operations.length} reconhecidas?`))return;try{const result=await api('/api/transactions/import',{method:'POST',data:{transactions:p.operations,name:p.name,keepDuplicates:$('#keep-duplicate-rows')?.checked===true}});S.preview=null;await update();render();toast(`${result.added} lançamentos importados, ${result.duplicates} duplicatas ignoradas.`);}catch(x){toast(x.message,true);}};};
 $('#example-csv').onclick=()=>download('metrics-modelo.csv','data;ticker;tipo;quantidade;preco;taxa;valor\n2026-10-01;MXRF11;compra;10;9,30;0;\n2026-10-15;MXRF11;dividendo;;;;1,00\n','text/csv;charset=utf-8');
 $('#upload-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>12*1024*1024)throw Error('Máximo de 12 MB.');$('#import-result').textContent='Analisando arquivo local...';const p=await api('/api/import/preview',{method:'POST',data:{name:f.name,data:await toBase64(f)}});S.preview={...p,name:f.name};$('#import-result').innerHTML=importPreviewHTML();hook();}catch(x){S.preview=null;$('#import-result').textContent=x.message;toast(x.message,true);}};
 $$('[data-remove-snapshot]').forEach(x=>x.onclick=async()=>{if(!confirm('Excluir esta posição importada? Os lançamentos manuais serão preservados.'))return;try{await api('/api/snapshots/'+x.dataset.removeSnapshot,{method:'DELETE'});await update();render();toast('Extrato excluído.');}catch(err){toast(err.message,true);}});
 $$('[data-rollback]').forEach(x=>x.onclick=async()=>{if(!confirm('Desfazer todas as operações deste lote?'))return;try{await api('/api/imports/rollback',{method:'POST',data:{id:x.dataset.rollback}});await update();render();toast('Lote desfeito.');}catch(e){toast(e.message,true);}});hook();}
function bindDocs(){$$('[data-remove-doc]').forEach(x=>x.onclick=async()=>{if(!confirm('Excluir documento armazenado?'))return;await api('/api/documents/'+x.dataset.removeDoc,{method:'DELETE'});await update();render();});$$('[data-read-doc]').forEach(x=>x.onclick=async()=>{const d=await api('/api/documents/'+x.dataset.readDoc);$('#doc-reading').classList.remove('hide');$('#doc-title').textContent=d.title;$('#doc-text').textContent=d.text;$('#doc-reading').scrollIntoView({behavior:'smooth'});});$$('[data-analyze-doc]').forEach(x=>x.onclick=()=>{const d=S.documents.find(d=>d.id===x.dataset.analyzeDoc);S.ai.context=true;go('ai');$('#chat-question').value=`Analise o documento "${d.title}" sobre ${d.ticker||'investimentos'}. Resuma fatos, riscos, indicadores, limitações e cite sua data-base.`;});}
function bindReports(){
 bindTaxDossier();
 $('#calculate-ledger').onclick=async()=>{try{S.taxLedger=await api('/api/tax/ledger?year='+encodeURIComponent($('#tax-year').value));$('#tax-detail').innerHTML=taxDetail();}catch(e){toast(e.message,true);}};
 $('#export-xlsx').onclick=async()=>{try{const y=$('#tax-year').value;const result=await api('/api/report/xlsx?year='+encodeURIComponent(y));downloadBase64(result.filename,result.base64,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');toast('Relatório XLSX gerado com avisos de conferência.');}catch(e){toast(e.message,true);}};
 $('#export-ledger').onclick=async()=>{try{const d=S.taxLedger||await api('/api/tax/ledger?year='+encodeURIComponent($('#tax-year').value));download('metrics-apuracao-auxiliar-'+d.year+'.csv',csv([['data','ticker','classe','venda_bruta','taxas','custo_atribuido','resultado','possivel_day_trade'],...d.sales.map(x=>[x.date,x.ticker,x.kind,x.gross,x.fees,x.allocatedCost,x.gain,x.possibleDayTrade?'SIM':'NÃO'])]),'text/csv');}catch(e){toast(e.message,true);}};
 const header=['data','ticker','tipo','quantidade','preco','taxa','valor','origem'];const rows=ts=>[header,...ts.map(t=>[t.date,t.ticker,t.type,t.quantity,t.price,t.fee,t.amount,t.source])];$('#export-year').onclick=()=>{const y=$('#tax-year').value;download('metrics-relatorio-'+y+'.csv',csv(rows(S.transactions.filter(t=>t.date.startsWith(y)))),'text/csv');};$('#export-transactions').onclick=()=>download('metrics-historico.csv',csv(rows(S.transactions)),'text/csv');$('#export-income').onclick=()=>download('metrics-proventos-mensais.csv',csv([['mes','valor'],...S.analytics.dividendsByMonth]),'text/csv');$('#export-positions').onclick=()=>download('metrics-posicoes.csv',csv([['ticker','quantidade','preco_medio','custo','dividendos'],...S.summary.positions.map(p=>[p.ticker,p.quantity,p.average,p.cost,p.dividends])]),'text/csv');$('#print-report').onclick=()=>{const year=$('#tax-year').value;const tx=S.transactions.filter(t=>t.date.startsWith(year));const wrap=document.createElement('section');wrap.className='print-report';wrap.innerHTML=`<h1>Metrics Investimentos · Relatório auxiliar ${esc(year)}</h1><p>Gerado em ${dateBR(today())}. Dados informados pelo usuário; não é documento fiscal oficial.</p><h2>Operações no ano</h2>${txTable(tx,false)}<h2>Posições em 31/12 (calculadas dos lançamentos disponíveis)</h2><p>Valores calculados, não comprovados. Concilie com extratos e notas oficiais.</p><div class="table-wrap"><table><thead><tr><th>Ticker</th><th>Quantidade</th><th>Custo histórico calculado</th></tr></thead><tbody>${(S.taxLedger?.year===year?S.taxLedger.yearEndPositions:[]).map(p=>`<tr><td>${esc(p.ticker)}</td><td>${fmt(p.quantity,6)}</td><td>${BRL(p.cost)}</td></tr>`).join('')}</tbody></table></div><p>Sem cálculo do ano? Clique primeiro em calcular os resultados fiscais; nenhum número foi inferido da posição atual.</p><p>Confira informes oficiais, operações faltantes e regras tributárias aplicáveis.</p>`;document.body.append(wrap);window.print();setTimeout(()=>wrap.remove(),1200);};}
function bindSettings(){$('#backup').onclick=async()=>{const password=prompt('Crie uma senha forte (mínimo 12 caracteres) para criptografar seu backup:');if(password===null)return;if(password.length<12)return toast('Use no mínimo 12 caracteres.',true);try{const data=await api('/api/backup/encrypted',{method:'POST',data:{password}});download('metrics-backup-protegido-'+today()+'.json',JSON.stringify(data,null,2),'application/json');toast('Backup protegido exportado. Guarde a senha: não é recuperável.');}catch(err){toast(err.message,true);}};$('#restore-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>10*1024*1024)throw Error('Backup grande demais.');const raw=JSON.parse(await f.text());if(!confirm('RESTAURAR irá SUBSTITUIR os dados da CARTEIRA selecionada. Outras carteiras não serão alteradas. Você fez backup?'))return;if(raw.kind==='metrics-encrypted-backup'){const password=prompt('Informe a senha do backup criptografado:');if(password===null)return;await api('/api/backup/restore-encrypted',{method:'POST',data:{backup:raw,password}});}else{if(!confirm('Backup antigo sem criptografia. Confirma que deseja restaurá-lo?'))return;await api('/api/restore',{method:'POST',data:raw});}await update();render();toast('Backup restaurado.');}catch(x){toast(x.message,true);}};}

function radar(){
 const quality=S.quality||{},data=quality.portfolio||{},xirr=quality.xirr||{},r=S.radar||{},alerts=r.alerts?.items||[],rank=r.screener?.items||[],goal=r.goal||{};
 const note=quality.fiscalWarnings?.length?`${quality.fiscalWarnings.length} pendências fiscais na carteira`:'Confira os relatórios fiscais antes de declarar';
 return `${head('INTELIGÊNCIA PATRIMONIAL','Radar e fundamentos','Conferência de origem, rentabilidade XIRR, ativos desejados, metas e pesquisa de fundamentos.')}
 <div class="metrics">${card('Valor de mercado comprovável',data.complete?BRL(data.totalMarketValue):'Incompleto',data.complete?'Todas as posições com preço':'Há ativos sem cotação')}${card('XIRR anualizada',xirr.value===null||xirr.value===undefined?'Indisponível':fmt(xirr.value,3)+'%',esc(xirr.reason||'Fluxos de caixa e cotação datada, não previsão'))}${card('Alertas locais',alerts.length,`Verificados ao abrir a tela`)}${card('Conferência fiscal','Revisão necessária',esc(note))}</div>
 <div class="grid-2"><section class="card"><h2>Qualidade e cobertura de dados</h2>${(data.warnings||[]).map(w=>`<p class="small danger-text">⚠ ${esc(w)}</p>`).join('')||(data.holdings?.length?'<p class="small positive">Sem lacunas básicas detectadas nos preços atuais.</p>':'<p class="small muted">Cadastre operações para avaliar a cobertura da carteira.</p>')}<p class="small muted">${esc(xirr.method||xirr.reason||'Rentabilidade sujeita à verificação dos lançamentos.')}</p>${data.allocation?`<h3>Distribuição por classe</h3><div class="table-wrap"><table class="table"><thead><tr><th>Classe</th><th>Valor observado</th><th>Participação</th></tr></thead><tbody>${data.allocation.map(x=>`<tr><td>${esc(x.type)}</td><td>${BRL(x.value)}</td><td>${fmt(x.percent)}%</td></tr>`).join('')}</tbody></table></div>`:'<div class="section-note">Sem dados suficientes para apurar percentuais da carteira inteira.</div>'}</section>
 <section class="card"><h2>Alertas fundamentados</h2>${alerts.length?alerts.map(x=>`<div class="watch-row"><div><b>${esc(x.title)}</b><p class="small muted">${esc(x.detail)}</p>${x.stale?'<p class="danger-text small">Preço antigo: não conclua que o alvo continua atingido.</p>':''}</div></div>`).join(''):'<div class="empty">Nenhum alerta pelas regras locais e dados disponíveis.</div>'}<p class="small muted">${esc(r.alerts?.warning||'Alertas dependem dos dados cadastrados.')}</p></section></div>
 <div class="grid-2 spaced"><section class="card"><h2>Pesquisa de indicadores externos</h2><p class="lead">O acesso a alguns fundamentos e proventos exige plano pago do fornecedor. O Metrics não inventará campos ausentes.</p>
 <form id="research-form"><div class="form-grid two"><label class="field">Ticker<input class="input" name="ticker" placeholder="MXRF11" required maxlength="24"></label><label class="field">Dataset<select class="input" name="kind"><option value="FII_INDICATORS">Indicadores de FII</option><option value="FII_DIVIDENDS">Proventos de FII</option><option value="STOCK_STATISTICS">Indicadores de ação</option><option value="STOCK_DIVIDENDS">Proventos de ação</option></select></label></div><label class="field">Chave brapi da sua conta<input class="input" type="password" id="research-key" autocomplete="off" placeholder="Não será armazenada na carteira"></label><div class="form-actions"><button class="btn primary">Consultar fornecedor</button></div></form><div id="research-preview"><p class="small muted">Nenhuma consulta realizada nesta sessão.</p></div></section>
 <section class="card"><h2>Meta opcional de proventos</h2><form id="goal-form"><label class="field">Meta mensal (R$)<input class="input" type="number" name="monthlyIncomeGoal" min="0" max="1000000000" step="0.01" value="${S.settings?.monthlyIncomeGoal??''}" placeholder="Ex.: 1000"></label><button class="btn spaced-mini">Salvar meta</button></form>${goal.configured?`<div class="summary-chip spaced-mini"><div class="small muted">Média histórica registrada</div><div class="value">${goal.averageMonthly===undefined?'Sem histórico':BRL(goal.averageMonthly)}</div><p class="small">Meta: ${BRL(goal.monthlyTarget)} · Progresso: ${goal.progress===null?'indisponível':fmt(goal.progress)+'%'}</p><p class="small muted">${esc(goal.warning||goal.reason||'')}</p></div>`:'<p class="small muted">Nenhuma meta cadastrada.</p>'}<p class="small muted">Uma meta não cria rendimentos e não gera recomendação de compra.</p></section></div>
 <section class="card spaced"><div class="card-header"><h2>Comparador de indicadores registrados</h2><span class="pill">Somente ativos da sua base</span></div><label class="field">Ordenar por<select class="input" id="rank-sort"><option value="DY" ${S.rankSort==='DY'?'selected':''}>Dividend yield</option><option value="PVP" ${S.rankSort==='PVP'?'selected':''}>P/VP crescente</option><option value="EQUITY" ${S.rankSort==='EQUITY'?'selected':''}>Patrimônio</option></select></label>${rank.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Ativo</th><th>Classe</th><th>DY 12m</th><th>P/VP</th><th>Patrimônio</th><th>Data-base</th></tr></thead><tbody>${rank.map(x=>`<tr><td>${esc(x.ticker)}</td><td>${esc(x.type)}</td><td>${x.dy12===null?'Não informado':fmt(x.dy12)+'%'}</td><td>${x.pvp===null?'Não informado':fmt(x.pvp,3)}</td><td>${x.equity===null?'Não informado':BRL(x.equity)}</td><td>${esc(x.asOf||'Não informada')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Cadastre uma ficha na seção Analisar e consulte indicadores, quando disponíveis, para comparar.</div>'}<p class="small muted">Ranking não é recomendação nem cobertura completa do mercado. Valores de fontes diferentes podem ter datas e definições diferentes.</p></section>`;
}
function bindRadar(){
 $('#rank-sort').onchange=async e=>{S.rankSort=e.target.value;try{S.radar=await api('/api/radar?sort='+encodeURIComponent(S.rankSort));render();}catch(err){toast(err.message,true);}};
 $('#goal-form').onsubmit=async e=>{e.preventDefault();try{const r=await api('/api/goals',{method:'POST',data:formValue(e.currentTarget)});await update();render();toast('Meta registrada no dispositivo.');}catch(err){toast(err.message,true);}};
 $('#research-form').onsubmit=async e=>{e.preventDefault();const data=formValue(e.currentTarget),key=$('#research-key').value;S.providerKey=key;
  try{const r=await api('/api/research/preview',{method:'POST',data:{...data,key}});S.providerPreview=r;
   const box=$('#research-preview');box.innerHTML=`<div class="section-note"><b>Fonte:</b> ${esc(r.source)}<p class="small">${esc(r.warnings?.join(' ')||'Confira a fonte.')} Data-base: ${esc(r.observedAt||'não informada')}.</p><pre class="doc-preview">${esc(JSON.stringify(r.indicators||r.events||r.records,null,2).slice(0,14000))}</pre><button class="btn primary" id="save-provider-data">Conferi o resultado: salvar</button></div>`;
   $('#save-provider-data').onclick=async()=>{try{let result;if(r.events)result=await api('/api/dividends/provider-import',{method:'POST',data:{events:r.events}});else result=await api('/api/research/save',{method:'POST',data:r});await update();render();toast(`Dados salvos após confirmação. ${r.events?result.added+' eventos novos':''}`);}catch(err){toast(err.message,true);}};
  }catch(err){toast(err.message,true);$('#research-preview').textContent=err.message;}
 };
}
function corporateForm(){return `<section class="card spaced"><h2>Eventos societários</h2><p class="small muted">Desdobramento e grupamento ajustam quantidades sem criar lucro. Bonificação exige conferir o custo fiscal no informe da companhia. Antes de lançar, mantenha um backup.</p><form id="corporate-form"><div class="form-grid two"><label class="field">Ticker<input class="input" name="ticker" placeholder="MXRF11" required></label><label class="field">Data<input class="input" name="date" type="date" required value="${today()}"></label><label class="field">Evento<select class="input" name="type"><option value="SPLIT">Desdobramento</option><option value="REVERSE_SPLIT">Grupamento</option><option value="BONUS">Bonificação</option></select></label><label class="field">Fator (novo / antigo)<input class="input" name="factor" type="number" step="any" min="0.000001" value="2"></label><label class="field">Quantidade bonificada (somente bonificação)<input class="input" name="quantity" type="number" min="0" step="any" value="0"></label><label class="field">Custo atribuído (R$) na bonificação<input class="input" name="basis" type="number" min="0" step="0.01" value="0"></label></div><label class="field"><input type="checkbox" id="corporate-review" required> Conferi o evento com documento da instituição.</label><button class="btn primary spaced-mini">Registrar evento revisado</button></form></section>`;}
const originalWallet=wallet;
wallet=function(){return originalWallet()+corporateForm();};
pages.wallet=wallet;


// Independent local portfolios. Every API request includes the selected portfolio ID.
async function changeActivePortfolio(id){
 if(id===S.portfolioId)return;
 await api('/api/portfolios/select',{method:'POST',data:{id}});
 S.portfolioId=id;S.page='dashboard';S.preview=null;S.taxLedger=null;S.lastSimulation=null;S.lastMulti=null;S.performance=null;S.quality=null;S.radar=null;S.providerPreview=null;S.extensionViews={};
 await update();await refreshExtensions();render();toast('Carteira selecionada. Histórico e memória da IA são independentes.');
}
function bindPortfolioControls(){const sel=$('#portfolio-switch');if(sel)sel.onchange=async()=>{try{await changeActivePortfolio(sel.value);}catch(e){toast(e.message,true);render();}};}
function portfolioPage(){
 const rows=S.portfolios||[];
 return `${head('ORGANIZAÇÃO LOCAL','Minhas carteiras','Cada carteira tem seus próprios lançamentos, desejos, documentos e memória da IA. Não são contas de usuários diferentes.')}
 <section class="card"><h2>Criar nova carteira</h2><p class="small muted">Uma nova carteira começa vazia e não copia operações nem indicadores da carteira principal.</p><form id="new-portfolio" class="form-grid two"><label class="field">Nome da carteira<input class="input" name="name" maxlength="50" required placeholder="Ex.: Carteira de longo prazo"></label><button class="btn primary" style="align-self:end">Criar carteira</button></form></section>
 <section class="card spaced"><h2>Carteiras deste dispositivo</h2><div class="table-wrap"><table class="table"><thead><tr><th>Nome</th><th>Identificação</th><th>Ações</th></tr></thead><tbody>${rows.map(p=>`<tr><td><b>${esc(p.name)}</b>${p.id===S.portfolioId?' · selecionada':''}</td><td class="small muted">${esc(p.id.slice(0,8))}</td><td><button class="btn smol" data-portfolio-select="${esc(p.id)}" ${p.id===S.portfolioId?'disabled':''}>Abrir</button> <button class="btn smol" data-portfolio-rename="${esc(p.id)}">Renomear</button> <button class="btn smol danger" data-portfolio-delete="${esc(p.id)}" ${rows.length===1?'disabled':''}>Excluir vazia</button></td></tr>`).join('')}</tbody></table></div><p class="small muted">Backup e relatórios são exportados apenas da carteira selecionada. Extensões pedem permissão separadamente para cada carteira. Antes de atualizar o aplicativo, exporte um backup de cada carteira.</p></section>`;
}
function bindPortfolioPage(){
 $('#new-portfolio').onsubmit=async e=>{e.preventDefault();try{const form=new FormData(e.currentTarget),r=await api('/api/portfolios',{method:'POST',data:{name:form.get('name')}});await update();render();toast('Carteira criada. Use Abrir para selecioná-la.');}catch(e){toast(e.message,true);}};
 $$('[data-portfolio-select]').forEach(b=>b.onclick=async()=>{try{await changeActivePortfolio(b.dataset.portfolioSelect);}catch(e){toast(e.message,true);}});
 $$('[data-portfolio-rename]').forEach(b=>b.onclick=async()=>{const current=S.portfolios.find(x=>x.id===b.dataset.portfolioRename);const name=prompt('Novo nome da carteira:',current?.name||'');if(name===null)return;try{await api('/api/portfolios/'+b.dataset.portfolioRename,{method:'PUT',data:{name}});await update();render();toast('Nome atualizado.');}catch(e){toast(e.message,true);}});
 $$('[data-portfolio-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Excluir somente se esta carteira estiver completamente vazia?'))return;try{await api('/api/portfolios/'+b.dataset.portfolioDelete,{method:'DELETE'});S.portfolioId=null;await update();await refreshExtensions();render();toast('Carteira vazia excluída.');}catch(e){toast(e.message,true);}});
}
function extensionPage(){
 return `${head('COMUNIDADE COM PERMISSÕES','Extensões','Painéis declarativos de leitura. Extensões não executam código, não fazem requisições externas e não alteram operações.')}
 <section class="card"><h2>Instalar pacote comunitário (.json)</h2><p class="small muted">Verifique a procedência do arquivo. O Metrics rejeita campos executáveis, HTML, URLs e permissões não reconhecidas. Instalar não habilita a extensão.</p><label class="field">Arquivo de manifesto<input type="file" class="input" id="extension-upload" accept=".json,application/json"></label><div id="extension-upload-warning" class="small muted">A ativação e as permissões serão escolhidas separadamente em cada carteira.</div></section>
 <section class="card spaced"><h2>Extensões instaladas</h2>${S.extensions?.length?S.extensions.map(p=>`<div class="summary-chip spaced-mini"><h3>${esc(p.name)} <span class="small muted">v${esc(p.version)}</span></h3><p class="small muted">${esc(p.description)}</p><form data-extension-form="${esc(p.id)}"><p class="small">Acesso de leitura nesta carteira:</p>${p.capabilities.map(cap=>`<label class="toggle" style="display:block;margin:8px 0"><input type="checkbox" name="capability" value="${esc(cap)}" ${p.grantedCapabilities.includes(cap)?'checked':''}> ${esc(cap)}</label>`).join('')}<label class="toggle" style="display:block;margin:10px 0"><input type="checkbox" name="enabled" ${p.enabled?'checked':''}> Habilitar nesta carteira</label><button class="btn primary">Salvar permissões</button> <button type="button" class="btn" data-ext-dashboard="${esc(p.id)}" ${!p.enabled?'disabled':''}>Visualizar painel</button> <button type="button" class="btn danger" data-ext-delete="${esc(p.id)}">Desinstalar</button></form>${S.extensionViews[p.id]?extensionWidgets(S.extensionViews[p.id]):''}</div>`).join(''):'<div class="empty">Nenhuma extensão instalada. Consulte o exemplo incluso no projeto em community-examples/.</div>'}</section>
 <section class="section-note">Segurança: os pacotes atuais são apenas configurações JSON, não plugins com código JavaScript/Python. Extensões com execução própria exigiriam outra revisão de permissões e auditoria de sandbox antes de serem permitidas.</section>`;
}
function extensionWidgets(view){return `<div class="spaced"><h3>Visualização: ${esc(view.name)}</h3>${view.widgets.map(w=>w.type==='metric'?`<div class="summary-chip">${esc(w.title)}: <b>${fmt(w.value,4)}</b></div>`:w.type==='unavailable'?`<p class="small muted">${esc(w.title)}: ${esc(w.reason)}</p>`:`<h3>${esc(w.title)}</h3><div class="table-wrap"><table class="table"><thead><tr>${w.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${w.rows.map(row=>`<tr>${w.columns.map(c=>`<td>${esc(row[c]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`).join('')}</div>`;}
async function refreshExtensions(){S.extensions=(await api('/api/extensions')).extensions;}
function bindExtensionsPage(){
 $('#extension-upload').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>30000)throw Error('Manifesto maior que 30 KB.');const manifest=JSON.parse(await file.text());const r=await api('/api/extensions/import',{method:'POST',data:{manifest}});await refreshExtensions();render();toast('Extensão instalada, mas desativada. Autorize as permissões para esta carteira.');}catch(err){toast(err.message,true);}};
 $$('[data-extension-form]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const id=form.dataset.extensionForm;try{const enabled=!!form.querySelector('[name=enabled]').checked;const capabilities=[...form.querySelectorAll('[name=capability]:checked')].map(x=>x.value);await api('/api/extensions/'+encodeURIComponent(id)+'/permissions',{method:'POST',data:{enabled,capabilities}});delete S.extensionViews[id];await refreshExtensions();render();toast('Permissões aplicadas somente nesta carteira.');}catch(err){toast(err.message,true);}});
 $$('[data-ext-dashboard]').forEach(b=>b.onclick=async()=>{try{S.extensionViews[b.dataset.extDashboard]=await api('/api/extensions/'+encodeURIComponent(b.dataset.extDashboard)+'/dashboard');render();}catch(err){toast(err.message,true);}});
 $$('[data-ext-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Desinstalar extensão de todas as carteiras? Os investimentos permanecerão intactos.'))return;try{await api('/api/extensions/'+encodeURIComponent(b.dataset.extDelete),{method:'DELETE'});delete S.extensionViews[b.dataset.extDelete];await refreshExtensions();render();toast('Extensão removida.');}catch(err){toast(err.message,true);}});
}

// Metrics 1.1 beta: segregated investment classes, currency provenance, and tax evidence.
const CLASSES_V11=[['ACAO','Ação Brasil'],['FII','Fundo imobiliário'],['ETF','ETF Brasil'],['BDR','BDR'],['FIAGRO','Fiagro'],['FUND','Fundo'],['FIXED_INCOME_BR','Renda fixa brasileira'],['STOCK_FOREIGN','Ação internacional'],['ETF_FOREIGN','ETF internacional'],['BOND_FOREIGN','Título internacional'],['CASH','Saldo em conta'],['OTHER','Outro']];
const CCY_V11=['BRL','USD','EUR','GBP','CAD','JPY','CHF','AUD'];
const optionsV11=(list)=>list.map(x=>Array.isArray(x)?`<option value="${esc(x[0])}">${esc(x[1])}</option>`:`<option value="${esc(x)}">${esc(x)}</option>`).join('');
const moneyV11=(value,currency='BRL')=>value==null?'Não calculável':new Intl.NumberFormat('pt-BR',{style:'currency',currency}).format(Number(value));
function assetClassesPage(){
 const foreign=S.foreignPositions||[],fixed=S.fixedIncome||[],instruments=S.instruments||[],fx=S.fxRates||[];
 return `${head('COBERTURA DE ATIVOS','Classes e exterior','Registre contratos em suas moedas originais. Não misturamos reais com dólares nem confundimos juros contratuais com preço de mercado.')}
 <div class="grid-2"><section class="card"><h2>Cadastrar tipo de ativo</h2><form id="instrument-v11"><div class="form-grid two"><label class="field">Código<input class="input" name="ticker" required placeholder="AAPL ou CDB2029"></label><label class="field">Classe<select class="input" name="assetClass">${optionsV11(CLASSES_V11)}</select></label><label class="field">Moeda<select class="input" name="currency">${optionsV11(CCY_V11)}</select></label><label class="field">Mercado<input name="market" class="input" value="MANUAL"></label><label class="field wide">Nome do ativo<input class="input" name="name"></label><label class="field wide">Fonte da classificação<input name="source" class="input" value="Informado pelo usuário" required></label></div><button class="btn primary spaced-mini">Salvar classificação</button></form><p class="section-note">Operações brasileiras continuam em Carteira. Operações internacionais ficam em um livro separado, sem conversão arbitrária.</p></section>
 <section class="card"><h2>Instrumentos cadastrados</h2>${instruments.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Ativo</th><th>Classe</th><th>Moeda</th><th></th></tr></thead><tbody>${instruments.map(x=>`<tr><td>${esc(x.ticker)}</td><td>${esc(x.assetClass)}</td><td>${esc(x.currency)}</td><td><button class="btn smol danger" data-delete-instrument="${esc(x.ticker)}">Excluir</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Classifique um ativo para começar.</div>'}</section></div>
 <div class="grid-2 spaced"><section class="card"><h2>Nova aplicação de renda fixa</h2><form id="fixed-form-v11"><div class="form-grid two"><label class="field">Identificador do contrato<input class="input" name="ticker" placeholder="CDB2029" required></label><label class="field">Nome<input class="input" name="name" placeholder="CDB Banco X"></label><label class="field">Moeda<select class="input" name="currency">${optionsV11(CCY_V11)}</select></label><label class="field">Principal aplicado<input class="input" name="principal" type="number" step="0.01" min="0.01" required></label><label class="field">Aplicação<input class="input" name="startDate" type="date" required></label><label class="field">Vencimento<input class="input" name="maturityDate" type="date" required></label><label class="field">Indexador<select class="input" name="rateKind"><option value="PREFIXED">Prefixado (estimativa bruta)</option><option value="CDI_PERCENT">% do CDI (sem estimativa automática)</option><option value="IPCA_PLUS">IPCA + taxa (sem estimativa automática)</option><option value="UNKNOWN">Não informado</option></select></label><label class="field">Taxa anual contratada (%)<input class="input" name="annualRate" type="number" min="0" max="300" step="any" value="10"></label><label class="field wide">Instituição e fonte<input class="input" name="source" placeholder="Contrato / comprovante" required></label></div><button class="btn primary spaced-mini">Cadastrar contrato</button></form></section>
 <section class="card"><h2>Renda fixa registrada</h2><p class="small muted">A estimativa de prefixados usa juros compostos ACT/365, não marcação a mercado. Taxas, impostos e condições reais de liquidez não estão embutidos.</p>${fixed.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Contrato</th><th>Principal</th><th>Condição</th><th>Resgate bruto estimado*</th><th>Ações</th></tr></thead><tbody>${fixed.map(x=>`<tr><td>${esc(x.name)}<div class="small muted">${esc(x.ticker)} · ${esc(x.currency)}</div></td><td>${moneyV11(x.principal,x.currency)}</td><td>${esc(x.rateKind)} · ${x.annualRate??'n/d'}%</td><td>${x.rateKind==='PREFIXED'?'Ver consulta de posição':'Não calculável'}</td><td><button class="btn smol" data-edit-fixed-v11="${esc(x.id)}">Editar</button> <button class="btn smol" data-redeem-v11="${esc(x.id)}">Resgate</button><button class="btn smol danger" data-delete-fixed-v11="${esc(x.id)}">Excluir sem resgates</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhum contrato cadastrado.</div>'}<button class="btn spaced-mini" id="compute-fixed-v11">Conferir valores brutos calculáveis</button><div id="fixed-report-v11"></div></section></div>
 <div class="grid-2 spaced"><section class="card"><h2>Operação internacional</h2><form id="foreign-form-v11"><div class="form-grid two"><label class="field">Ticker<input class="input" name="ticker" placeholder="AAPL" required></label><label class="field">Moeda<select class="input" name="currency">${optionsV11(CCY_V11.filter(x=>x!=='BRL'))}</select></label><label class="field">Operação<select class="input" name="type"><option value="BUY">Compra</option><option value="SELL">Venda</option><option value="DIVIDEND">Provento recebido</option></select></label><label class="field">Data<input class="input" name="date" type="date" required></label><label class="field">Quantidade (compra/venda)<input class="input" name="quantity" type="number" min="0" step="any" value="1"></label><label class="field">Preço por unidade (moeda original)<input class="input" name="price" type="number" min="0" step="any" value="1"></label><label class="field">Custos na moeda original<input class="input" name="fee" type="number" min="0" step="any" value="0"></label><label class="field">Provento bruto (se aplicável)<input class="input" name="amount" type="number" min="0" step="any" value="0"></label><label class="field wide">Origem<input class="input" name="source" value="Registro manual"></label></div><button class="btn primary spaced-mini">Salvar operação</button></form></section>
 <section class="card"><h2>Livro internacional, sem conversão fictícia</h2>${foreign.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Ativo</th><th>Moeda</th><th>Quantidade</th><th>Custo</th><th>Resultado realizado*</th></tr></thead><tbody>${foreign.map(x=>`<tr><td>${esc(x.ticker)}</td><td>${esc(x.currency)}</td><td>${fmt(x.quantity,6)}</td><td>${moneyV11(x.cost,x.currency)}</td><td>${moneyV11(x.realizedNative,x.currency)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhuma posição internacional.</div>'}<p class="small muted">* Resultado na moeda original, antes de regras fiscais, câmbio efetivo e impostos. É possível editar, excluir e desfazer o último ajuste.</p><button class="btn smol spaced-mini" id="undo-foreign-v11">↶ Desfazer última alteração internacional</button>${(S.foreignTrades||[]).slice(-30).reverse().map(t=>`<div class="watch-row"><span>${esc(t.date)} · ${esc(t.ticker)} · ${esc(t.type)} · ${esc(t.currency)}</span><button class="btn smol" data-edit-foreign-v11="${esc(t.id)}">Editar</button> <button class="btn smol danger" data-remove-foreign-v11="${esc(t.id)}">Excluir</button></div>`).join('')}</section></div>
 <div class="grid-2 spaced"><section class="card"><h2>PTAX do Banco Central</h2><form id="ptax-form-v11" class="form-grid two"><label class="field">Moeda<select class="input" name="currency">${optionsV11(CCY_V11.filter(x=>x!=='BRL'))}</select></label><label class="field">De<input class="input" type="date" name="from" required></label><label class="field">Até<input class="input" type="date" name="to" required></label><button class="btn primary" style="align-self:end">Consultar taxas oficiais</button></form><div class="section-note">PTAX venda: taxa oficial de referência, não a cotação efetiva da corretora. A consulta requer internet.</div></section>
 <section class="card"><h2>Câmbio registrado e conversão</h2><p class="small muted">${fmt(fx.length,0)} taxas PTAX ou manuais salvas. O Metrics só converte quando existe taxa na data solicitada ou próxima, dentro de limite explícito.</p><form id="convert-form-v11" class="form-grid two"><label class="field">Valor na moeda original<input class="input" type="number" name="amount" min="0" step="any" required></label><label class="field">Moeda<select class="input" name="currency">${optionsV11(CCY_V11.filter(x=>x!=='BRL'))}</select></label><label class="field">Data da avaliação<input class="input" type="date" name="date" required></label><button class="btn" style="align-self:end">Converter com fonte</button></form><div id="conversion-result-v11" class="section-note">Nenhuma conversão efetuada.</div></section></div>`;
}
function fiscalDossierUI(){return `<section class="card spaced"><div class="card-header"><h2>Dossiê fiscal com documentos</h2><span class="pill">Não gera DARF</span></div><p class="small muted">Compare proventos lançados com valores de informes, por ativo e natureza. O dossiê aponta diferenças e lacunas, sem declarar valores como certificados.</p><form id="fiscal-proof-v11"><div class="form-grid two"><label class="field">Ano-calendário<input class="input" type="number" name="year" min="2000" max="2200" required value="${new Date().getFullYear()-1}"></label><label class="field">Ticker<input class="input" name="ticker" required placeholder="MXRF11"></label><label class="field">Natureza<select class="input" name="nature"><option value="DIVIDEND">Dividendo</option><option value="JCP">JCP</option><option value="FII_INCOME">Rendimento FII</option><option value="AMORTIZATION">Amortização</option><option value="FIXED_INCOME">Renda fixa</option><option value="FOREIGN_INCOME">Exterior</option><option value="WITHHOLDING">Retenção</option><option value="OTHER">Outro</option></select></label><label class="field">Valor do documento (R$ ou valor original especificado)<input class="input" name="amount" type="number" min="0" step="0.01" required></label><label class="field wide">Informe/documento-fonte<input class="input" name="source" minlength="5" required placeholder="Informe de rendimentos 2025 — instituição X"></label></div><button class="btn primary spaced-mini">Registrar valor do informe</button></form><div class="row-actions spaced-mini"><button class="btn" id="dossier-load-v11">Verificar dossiê do ano</button><button class="btn" id="dossier-export-v11">Exportar dossiê JSON</button><a class="btn" href="https://www.gov.br/pt-br/servicos/apurar-imposto-sobre-renda-variavel" target="_blank" rel="noopener noreferrer">Abrir ReVar oficial</a></div><div id="dossier-output-v11" class="section-note">Selecione o ano e gere a conferência.</div></section>`;}
function noticesPage(){return `${head('ACOMPANHAMENTO','Comunicados e eventos','Registro verificável de notícias e fatos relevantes fornecidos pelo investidor. O Metrics não inventa notícias nem rastreia a web automaticamente.')}
<div class="grid-2"><section class="card"><h2>Salvar comunicação</h2><form id="notice-form-v11"><div class="form-grid two"><label class="field">Ativo<input class="input" name="ticker" required placeholder="GGRC11"></label><label class="field">Data<input class="input" name="date" type="date" required></label><label class="field wide">Título<input class="input" name="title" required minlength="5"></label><label class="field">Categoria<select class="input" name="category"><option value="DIVIDEND">Proventos</option><option value="EARNINGS">Resultados</option><option value="CORPORATE">Societário</option><option value="RISK">Risco</option><option value="OTHER">Outro</option></select></label><label class="field">Emissor/fonte<input class="input" name="source" required></label><label class="field wide">URL HTTPS do documento<input class="input" name="url" type="url" placeholder="https://..."></label><label class="field wide">Observações<input class="input" name="notes"></label></div><button class="btn primary spaced-mini">Salvar referência</button></form><p class="section-note">Os links fornecidos não são validados automaticamente quanto à veracidade. Consulte a fonte oficial antes de tomar decisões.</p></section><section class="card"><h2>Histórico de comunicados</h2>${(S.notices||[]).length?[...S.notices].sort((a,b)=>b.date.localeCompare(a.date)).map(n=>`<div class="watch-row"><div><b>${esc(n.ticker)}</b> · ${esc(dateBR(n.date))}<div>${esc(n.title)}</div><span class="small muted">${esc(n.source)} · não verificado automaticamente</span>${n.url?`<div><a href="${esc(n.url)}" target="_blank" rel="noopener noreferrer">Abrir documento informado ↗</a></div>`:''}</div><button class="btn smol danger" data-remove-notice-v11="${esc(n.id)}">Excluir</button></div>`).join(''):'<div class="empty">Nenhum comunicado registrado.</div>'}</section></div>`;}
function bindClasses(){
 $('#instrument-v11').onsubmit=async e=>{e.preventDefault();try{await api('/api/instruments',{method:'POST',data:formValue(e.currentTarget)});await update();render();toast('Classe e moeda salvas com fonte declarada.');}catch(err){toast(err.message,true);}};
 $('#fixed-form-v11').onsubmit=async e=>{e.preventDefault();try{await api('/api/fixed-income',{method:'POST',data:formValue(e.currentTarget)});await update();render();toast('Contrato registrado. Valor futuro não é promessa.');}catch(err){toast(err.message,true);}};
 $('#foreign-form-v11').onsubmit=async e=>{e.preventDefault();try{await api('/api/foreign/trades',{method:'POST',data:formValue(e.currentTarget)});await update();render();toast('Operação registrada na moeda original.');}catch(err){toast(err.message,true);}};
 $('#ptax-form-v11').onsubmit=async e=>{e.preventDefault();try{const r=await api('/api/fx/ptax',{method:'POST',data:formValue(e.currentTarget)});await update();render();toast(`PTAX: ${r.updated} observações oficiais registradas.`);}catch(err){toast(err.message,true);}};
 $('#convert-form-v11').onsubmit=async e=>{e.preventDefault();const p=formValue(e.currentTarget);try{const r=await api('/api/fx/convert?'+new URLSearchParams(p));$('#conversion-result-v11').textContent=r.converted===null?`Conversão indisponível: ${r.reason}. Não foi criada taxa fictícia.`:`${moneyV11(p.amount,p.currency)} = ${BRL(r.converted)} · ${r.rateDate} · ${r.source}. ${r.warning||''}`;}catch(err){toast(err.message,true);}};
 $('#compute-fixed-v11').onclick=async()=>{try{const r=await api('/api/asset-classes');$('#fixed-report-v11').innerHTML=(r.fixedIncome.positions||[]).map(x=>`<div class="section-note"><b>${esc(x.ticker)}</b>: principal restante ${moneyV11(x.remainingPrincipal,x.currency)} · estimativa bruta ${moneyV11(x.estimatedContractGross,x.currency)}<p>${esc(x.warning)}</p></div>`).join('')||'Sem aplicações.';}catch(err){toast(err.message,true);}};
 $$('[data-delete-instrument]').forEach(b=>b.onclick=async()=>{if(!confirm('Remover classificação do ativo sem operações?'))return;try{await api('/api/instruments/'+encodeURIComponent(b.dataset.deleteInstrument),{method:'DELETE'});await update();render();}catch(err){toast(err.message,true);}});
 $$('[data-delete-fixed-v11]').forEach(b=>b.onclick=async()=>{if(!confirm('Excluir contrato? Contratos com resgates não podem ser excluídos.'))return;try{await api('/api/fixed-income/'+b.dataset.deleteFixedV11,{method:'DELETE'});await update();render();}catch(err){toast(err.message,true);}});
 if($('#undo-foreign-v11'))$('#undo-foreign-v11').onclick=async()=>{const event=(S.foreignAudit||[]).filter(x=>!x.undoneAt).at(-1);if(!event)return toast('Sem correções recentes para desfazer.',true);try{await api('/api/foreign/undo',{method:'POST',data:{auditId:event.id}});await update();render();toast('Alteração internacional desfeita com saldo conferido.');}catch(err){toast(err.message,true);}};
 $$('[data-edit-foreign-v11]').forEach(b=>b.onclick=async()=>{const t=(S.foreignTrades||[]).find(x=>x.id===b.dataset.editForeignV11);if(!t)return;const date=prompt('Data YYYY-MM-DD:',t.date);if(date===null)return;const quantity=prompt('Quantidade (dividendos = 0):',t.quantity);if(quantity===null)return;const price=prompt('Preço unitário na moeda original:',t.price);if(price===null)return;const amount=prompt('Valor bruto do provento (se aplicável):',t.amount);if(amount===null)return;try{await api('/api/foreign/trades/'+t.id,{method:'PUT',data:{date,quantity,price,amount}});await update();render();toast('Operação internacional editada; posição recalculada.');}catch(err){toast(err.message,true);}});
 $$('[data-edit-fixed-v11]').forEach(b=>b.onclick=async()=>{const t=(S.fixedIncome||[]).find(x=>x.id===b.dataset.editFixedV11);if(!t)return;const principal=prompt('Principal contratual na moeda original:',t.principal);if(principal===null)return;const annualRate=prompt('Taxa contratada anual (%):',t.annualRate??'');if(annualRate===null)return;const maturityDate=prompt('Data de vencimento YYYY-MM-DD:',t.maturityDate);if(maturityDate===null)return;try{await api('/api/fixed-income/'+t.id,{method:'PUT',data:{principal,annualRate,maturityDate}});await update();render();toast('Contrato atualizado. Confira documento e rendimentos.');}catch(err){toast(err.message,true);}});
 $$('[data-remove-foreign-v11]').forEach(b=>b.onclick=async()=>{if(!confirm('Excluir operação internacional? A posição será recalculada.'))return;try{await api('/api/foreign/trades/'+b.dataset.removeForeignV11,{method:'DELETE'});await update();render();}catch(err){toast(err.message,true);}});
 $$('[data-redeem-v11]').forEach(b=>b.onclick=async()=>{const principal=prompt('Principal resgatado, na moeda contratual (sem juros):');if(principal===null)return;const received=prompt('Valor bruto total efetivamente recebido:');if(received===null)return;const date=prompt('Data do resgate YYYY-MM-DD:');if(date===null)return;try{await api('/api/fixed-income/'+b.dataset.redeemV11+'/redeem',{method:'POST',data:{date,principal,received,source:'Informado pelo investidor'}});await update();render();toast('Resgate registrado; apuração tributária requer informe da instituição.');}catch(err){toast(err.message,true);}});
}
function bindTaxDossier(){if(!$('#fiscal-proof-v11'))return;
 $('#fiscal-proof-v11').onsubmit=async e=>{e.preventDefault();try{await api('/api/tax/evidence',{method:'POST',data:formValue(e.currentTarget)});await update();render();toast('Valor do informe registrado para conciliação, não certificado.');}catch(err){toast(err.message,true);}};
 const load=async()=>{const year=$('#tax-year')?.value||String(new Date().getFullYear()-1);const data=await api('/api/tax/dossier?year='+encodeURIComponent(year));S.dossierV11=data;$('#dossier-output-v11').innerHTML=`<h3>Exercício ${esc(year)} · revisão obrigatória</h3><p class="small muted">${esc(data.disclaimer)}</p>${data.incomeDiscrepancies.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Ativo</th><th>Natureza</th><th>Lançado</th><th>Informe</th><th>Resultado</th></tr></thead><tbody>${data.incomeDiscrepancies.map(x=>`<tr><td>${esc(x.ticker)}</td><td>${esc(x.nature)}</td><td>${x.registered===null?'Ausente':BRL(x.registered)}</td><td>${x.informedByEvidence===null?'Ausente':BRL(x.informedByEvidence)}</td><td>${esc(x.status)}</td></tr>`).join('')}</tbody></table></div>`:''}<h3>Pendências para conferência</h3>${data.blockers.map(x=>`<p class="small">⚠ ${esc(x)}</p>`).join('')}<p>Renda fixa: ${fmt(data.otherAssets.length,0)} contrato(s) · Exterior: ${fmt(data.foreignAssets.length,0)} ativo(s). Os comprovantes continuam necessários.</p>`;return data;};
 $('#dossier-load-v11').onclick=async()=>{try{await load();}catch(err){toast(err.message,true);}};
 $('#dossier-export-v11').onclick=async()=>{try{const d=await load();download('metrics-dossie-fiscal-'+d.year+'.json',JSON.stringify(d,null,2),'application/json');}catch(err){toast(err.message,true);}};
}
function bindNotices(){
 $('#notice-form-v11').onsubmit=async e=>{e.preventDefault();try{await api('/api/notices',{method:'POST',data:formValue(e.currentTarget)});await update();render();toast('Comunicado registrado, sem verificação automática da fonte.');}catch(err){toast(err.message,true);}};
 $$('[data-remove-notice-v11]').forEach(b=>b.onclick=async()=>{if(!confirm('Excluir referência?'))return;try{await api('/api/notices/'+b.dataset.removeNoticeV11,{method:'DELETE'});await update();render();}catch(err){toast(err.message,true);}});
}
pages.classes=assetClassesPage;pages.notices=noticesPage;
const mainDashboardV11=pages.dashboard;pages.dashboard=()=>mainDashboardV11()+'<section class="section-note spaced"><b>Alcance do painel:</b> O patrimônio do dashboard resume operações brasileiras do livro de bolsa. Renda fixa, aplicações internacionais e moedas diferentes estão em <b>Classes e exterior</b>. O Metrics não soma moedas diferentes nem apresenta rendimento contratado de CDB como cotação negociável.</section>';
const originalTaxV11=pages.tax;pages.tax=()=>originalTaxV11()+fiscalDossierUI();

async function startup(){await update();await refreshExtensions();await refreshProvidersV14();render();}
/* Metrics 2.4: three non-authoritative, evidence-led workspaces. */
NAV.push(['wealth24','◈','Patrimônio total'],['official24','▧','Proventos CVM'],['fiscal24','▣','Fiscal anual']);
S.wealth24=null;S.evolution24=null;S.taxCase24=null;
const opts24=arr=>arr.map(([v,n])=>`<option value="${esc(v)}">${esc(n)}</option>`).join('');
pages.wealth24=()=>`${head('CONSOLIDAÇÃO','Patrimônio multiclasse','Bolsa brasileira, exterior, renda fixa, outras posições e caixa documentado, sem somar valores ausentes.')}<div class="card spaced">
 <form id="wealth-filter24" class="row-actions"><label class="field">Data-base<input class="input" type="date" name="date" value="${today()}" required></label><label class="field">Meses<input class="input" type="number" name="months" min="1" max="60" value="12" required></label><button class="btn primary">Recalcular</button></form>
 <div id="wealth-results24" class="section-note">Selecione Recalcular para recuperar avaliações datadas e lacunas.</div><div id="wealth-evolution24"></div>
 </div><div class="grid-2 spaced">
 <section class="card"><h2>Aportes e retiradas externas</h2><p class="small muted">Movimentação externa não é patrimônio. O investimento em ações ou CDB não deve ser registrado como retirada externa.</p><form id="flow-form24" class="form-grid two"><label class="field">Tipo<select class="input" name="type">${opts24([['DEPOSIT','Depósito'],['WITHDRAW','Retirada']])}</select></label><label class="field">Moeda<select class="input" name="currency">${opts24(['BRL','USD','EUR','GBP','CAD','JPY','CHF','AUD'].map(x=>[x,x]))}</select></label><label class="field">Valor<input class="input" type="number" name="amount" min="0.01" step="0.01" required></label><label class="field">Data<input class="input" type="date" name="date" value="${today()}" required></label><label class="field wide">Documento / origem<input class="input" name="source" required maxlength="180" placeholder="Extrato da corretora: referência"></label><button class="btn primary">Registrar fluxo</button></form>
 ${(S.externalFlows||[]).slice(-20).reverse().map(x=>`<p class="small">${esc(x.date)} · ${esc(x.type)} · ${esc(x.currency)} ${fmt(x.amount)} <button class="btn smol danger" data-remove-flow24="${esc(x.id)}">Excluir</button></p>`).join('')}</section>
 <section class="card"><h2>Avaliação documental de caixa, renda fixa ou outros</h2><p class="small muted">Use o ID do contrato para renda fixa e o identificador da conta para caixa. Para saldo zero, registre 0 acompanhado de extrato.</p><form id="valuation-form24" class="form-grid two"><label class="field">Classe<select class="input" name="assetClass">${opts24([['CASH','Caixa / conta'],['FIXED_INCOME','Renda fixa'],['OTHER','Outro investimento']])}</select></label><label class="field">Identificador<input class="input" name="assetKey" required placeholder="CONTA_BRL ou ID do contrato"></label><label class="field">Valor na moeda<input class="input" type="number" min="0" step="0.01" name="value" required></label><label class="field">Moeda<select class="input" name="currency">${opts24(['BRL','USD','EUR','GBP','CAD','JPY','CHF','AUD'].map(x=>[x,x]))}</select></label><label class="field">Data do extrato<input class="input" type="date" name="date" value="${today()}" required></label><label class="field wide">Origem do valor<input class="input" name="source" required placeholder="Extrato com data-base"></label><button class="btn primary">Registrar avaliação</button></form>
 ${(S.assetValuations||[]).slice(-20).reverse().map(x=>`<p class="small">${esc(x.assetClass)} · ${esc(x.assetKey)} · ${esc(x.date)} · ${esc(x.currency)} ${fmt(x.value)} <button class="btn smol danger" data-remove-valuation24="${esc(x.id)}">Excluir</button></p>`).join('')}</section></div>`;
pages.official24=()=>`${head('DOCUMENTOS PRIMÁRIOS','Proventos na CVM','Inspeção técnica do arquivo IPE: fonte, hash e extração cautelosa. O recebimento não é criado automaticamente.')}<section class="card spaced"><p class="small muted">Antes de verificar, importe o índice IPE em <b>APIs e provedores</b> vinculando CNPJ a ticker. Somente documentos com URL oficial podem ser consultados. A CVM não fornece um índice universal de valores por cota.</p><div id="official-output24" class="section-note">Selecione Inspecionar em um documento. A conferência automática exige conexão com o servidor CVM.</div><div class="table-wrap"><table class="table"><thead><tr><th>Entrega</th><th>Ativo</th><th>Documento</th><th>Ação</th></tr></thead><tbody>${(S.ipeIndex||[]).filter(x=>x.ticker&&x.sourceUrl).slice(0,80).map((x,i)=>`<tr><td>${esc(x.deliveryDate)}</td><td>${esc(x.ticker)}</td><td>${esc(x.title)}</td><td><button class="btn smol" data-ipe-inspect24="${i}">Inspecionar</button></td></tr>`).join('')}</tbody></table></div></section>
 <section class="card spaced"><h2>Inspeções e revisões locais</h2>${(S.officialChecks||[]).slice(-30).reverse().map(x=>`<div class="watch-row"><div><b>${esc(x.ticker)} · ${esc(x.documentId)}</b><p class="small muted">Consulta ${esc(x.checkedAt)} · SHA-256 ${esc(x.sha256)} · ${esc(x.reviewStatus)} · ${x.terms?.perUnit===null?'Valor por cota não identificado':BRL(x.terms.perUnit)+' por unidade (extraído)'}</p><p class="small">${esc(x.note)}</p></div>${x.reviewStatus==='PENDING'?`<div class="inline-buttons"><button class="btn smol" data-ipe-review24="${esc(x.id)}" data-status="CONFIRMED_BY_USER">Conferi</button><button class="btn smol" data-ipe-review24="${esc(x.id)}" data-status="DISMISSED">Descartar</button></div>`:''}</div>`).join('')||'<p class="muted">Sem inspeções.</p>'}</section>`;
pages.fiscal24=()=>`${head('DOSSIÊ AUDITÁVEL','Fiscal por exercício','Quadro mensal e lacunas documentais. A apuração definitiva e a revisão profissional acontecem fora do aplicativo.')}<section class="card spaced"><form class="row-actions" id="tax-load24"><label class="field">Ano-calendário<input class="input" name="year" id="tax-year24" type="number" min="2000" max="2200" value="${new Date().getFullYear()-1}" required></label><button class="btn primary">Gerar dossiê</button><button type="button" class="btn" id="tax-export24">Exportar JSON</button></form><div id="tax-output24" class="section-note">Nenhum imposto ou DARF é calculado sem todas as bases e validações.</div></section><section class="card spaced"><h2>Registrar parecer de revisão especializada</h2><p class="small muted">Transcrição local de um parecer externo. Este formulário não verifica a habilitação do revisor e não certifica a declaração. Inclua a referência do documento assinado, se existir.</p><form id="tax-review24" class="form-grid two"><label class="field">Ano-calendário<input class="input" type="number" name="year" min="2000" max="2200" value="${new Date().getFullYear()-1}" required></label><label class="field">Profissional / revisor<input class="input" name="reviewer" required minlength="4"></label><label class="field">Decisão<select class="input" name="decision">${opts24([['NEEDS_CHANGES','Exige correções'],['EVIDENCE_REVIEWED','Evidências examinadas']])}</select></label><label class="field">Parecer / protocolo<input class="input" name="documentId" required minlength="5"></label><label class="field wide">Escopo examinado<input class="input" name="scope" maxlength="400" placeholder="Notas, IRRF, prejuízos, exterior..."></label><label class="field wide">Fundamentação<textarea class="input" name="basis" required minlength="20" maxlength="1000" rows="4"></textarea></label><button class="btn primary">Guardar revisão declarada</button></form></section>`;
async function refreshWealth24(){const form=$('#wealth-filter24');if(!form)return;const f=formValue(form);try{const [v,e]=await Promise.all([api('/api/v24/patrimony?date='+encodeURIComponent(f.date)),api('/api/v24/evolution?date='+encodeURIComponent(f.date)+'&months='+encodeURIComponent(f.months))]);S.wealth24=v;S.evolution24=e;$('#wealth-results24').innerHTML=`<div class="metrics">${card('Total documentado',v.complete?BRL(v.totalBRL):'INCOMPLETO','Sem estimativas fictícias')}${card('Parcela conhecida',BRL(v.partialKnownBRL),'Não representa o total')}${card('Registros',String(v.positions.length),'Todas as classes sem duplicidade intencional')}${card('Lacunas',String(v.missing.length+v.issues.length),'Valores ou fontes exigidos')}</div><div class="table-wrap"><table class="table"><thead><tr><th>Classe</th><th>Identificador</th><th>Valor convertido</th><th>Origem</th></tr></thead><tbody>${v.positions.map(x=>`<tr><td>${esc(x.assetClass)}</td><td>${esc(x.assetKey)}</td><td>${x.valueBRL===null?'Pendente':BRL(x.valueBRL)}</td><td>${esc(x.source||'Não informado')} (${esc(x.valuationDate||'—')})</td></tr>`).join('')}</tbody></table></div>${v.missing.map(x=>`<p class="small danger-text">⚠ ${esc(x.assetKey||x.assetClass||'Pendência')}: ${esc(x.reason)}</p>`).join('')}${v.issues.map(x=>`<p class="small danger-text">⚠ ${esc(x)}</p>`).join('')}<p class="small muted">${esc(v.warning)}</p>`;
 $('#wealth-evolution24').innerHTML=`<h3>Evolução por mês</h3><div class="table-wrap"><table class="table"><thead><tr><th>Mês</th><th>Patrimônio completo</th><th>Parcela conhecida</th><th>Fluxo externo BRL</th></tr></thead><tbody>${e.points.map(p=>`<tr><td>${esc(p.date.slice(0,7))}</td><td>${p.complete?BRL(p.totalBRL):'Incompleto'}</td><td>${BRL(p.partialKnownBRL)}</td><td>${BRL(p.netExternalBRL)}</td></tr>`).join('')}</tbody></table></div><p class="small muted">${esc(e.warning)}</p>`;
 }catch(err){toast(err.message,true);}}
function bindWealth24(){if(!$('#wealth-filter24'))return;$('#wealth-filter24').onsubmit=e=>{e.preventDefault();refreshWealth24();};$('#flow-form24').onsubmit=async e=>{e.preventDefault();try{await api('/api/v24/external-flow',{method:'POST',data:formValue(e.currentTarget)});await update();render();await refreshWealth24();}catch(err){toast(err.message,true);}};$('#valuation-form24').onsubmit=async e=>{e.preventDefault();try{await api('/api/v24/valuation',{method:'POST',data:formValue(e.currentTarget)});await update();render();await refreshWealth24();}catch(err){toast(err.message,true);}};$('[data-remove-flow24]').forEach(b=>b.onclick=()=>removeMetrics24('external-flow',b.dataset.removeFlow24));$('[data-remove-valuation24]').forEach(b=>b.onclick=()=>removeMetrics24('valuation',b.dataset.removeValuation24));}
async function removeMetrics24(type,id){if(!confirm('Excluir este registro? A trilha de backup é recomendada.'))return;try{await api('/api/v24/'+type+'/'+id,{method:'DELETE'});await update();render();await refreshWealth24();}catch(e){toast(e.message,true);}}
function bindOfficial24(){const out=$('#official-output24');if(!out)return;const rows=(S.ipeIndex||[]).filter(x=>x.ticker&&x.sourceUrl).slice(0,80);$('[data-ipe-inspect24]').forEach(b=>b.onclick=async()=>{const x=rows[Number(b.dataset.ipeInspect24)];if(!x)return;out.textContent='Lendo documento oficial e calculando SHA-256...';try{const r=await api('/api/v24/official-check',{method:'POST',data:{documentId:x.documentId,ticker:x.ticker,sourceUrl:x.sourceUrl}});const p=r.check;const report24=`Arquivo recuperado da CVM: ${p.sourceUrl}\nHash SHA-256: ${p.sha256}\nData-com: ${p.terms.recordDate||'inconclusiva'} · Pagamento: ${p.terms.paymentDate||'inconclusivo'} · Valor unitário: ${p.terms.perUnit??'inconclusivo'}\n${p.terms.note}`;await update();render();$('#official-output24').textContent=report24;toast('Inspeção registrada, revisão humana necessária.');}catch(err){out.textContent=err.message;toast(err.message,true);}});$('[data-ipe-review24]').forEach(b=>b.onclick=async()=>{const note=prompt('Justifique a decisão após conferir o documento inteiro (mín. 12 caracteres):');if(note===null)return;try{await api('/api/v24/official-review',{method:'POST',data:{id:b.dataset.ipeReview24,status:b.dataset.status,note}});await update();render();toast('Revisão declarada salva, sem criar provento recebido.');}catch(err){toast(err.message,true);}});}
function bindFiscal24(){if(!$('#tax-load24'))return;$('#tax-load24').onsubmit=async e=>{e.preventDefault();try{const year=$('#tax-year24').value,r=await api('/api/v24/tax-case?year='+encodeURIComponent(year));S.taxCase24=r;$('#tax-output24').innerHTML=`<p><b>Ano-calendário ${r.year} · declaração ${r.reportingYear}</b> · imposto e DARF: indisponíveis.</p><div class="table-wrap"><table class="table"><thead><tr><th>Mês</th><th>Vendas</th><th>Resultado antes do imposto</th><th>Pendência</th></tr></thead><tbody>${r.months.map(m=>`<tr><td>${esc(m.month)}</td><td>${BRL(m.grossSalesBRL)}</td><td>${BRL(m.netRealizedBRL)}</td><td>${m.needsSpecialClassification?'Classificação especial':'Conferir IRRF/prejuízos'}</td></tr>`).join('')}</tbody></table></div><h3>Pontos pendentes</h3>${r.blockers.map(x=>`<p class="small">⚠ ${esc(x)}</p>`).join('')}<p class="small muted">Revisões declaradas: ${r.reviews.length}. ${esc(r.warning)}</p>`;}catch(err){toast(err.message,true);}};$('#tax-export24').onclick=()=>{if(!S.taxCase24 || String(S.taxCase24.year)!==$('#tax-year24').value)return toast('Gere o dossiê do ano selecionado antes de exportar.',true);download('metrics-fiscal-'+S.taxCase24.year+'.json',JSON.stringify(S.taxCase24,null,2),'application/json');};$('#tax-review24').onsubmit=async e=>{e.preventDefault();try{await api('/api/v24/tax-review',{method:'POST',data:formValue(e.currentTarget)});await update();render();toast('Parecer referenciado. Verificação profissional permanece externa.');}catch(err){toast(err.message,true);}};}
const baseRenderMetrics24=render;render=function(){baseRenderMetrics24();if(S.page==='wealth24')bindWealth24();if(S.page==='official24')bindOfficial24();if(S.page==='fiscal24')bindFiscal24();};


// LiteKit 2.5: read-only diagnostics, with no external telemetry.
NAV.push(['audit25','◉','Auditoria e desempenho']);
pages.audit25=()=>head('QUALIDADE E DESEMPENHO','Auditoria do Metrics','Diagnóstico local de integridade, fontes e lacunas. Nenhuma informação é transmitida a terceiros.')+
 '<section class="card spaced"><h2>Verificar a carteira selecionada</h2><p class="small muted">O relatório identifica dados em falta e sugere ações, mas não substitui revisão tributária, auditoria de segurança ou teste do executável.</p><button class="btn primary" id="audit-run25">Executar auditoria</button><button class="btn" id="audit-export25">Exportar relatório JSON</button><div id="audit-results25" class="section-note">Sem execução nesta sessão.</div></section>';
const beforeRenderAudit25=render;
render=function(){beforeRenderAudit25();if(S.page==='audit25'){
 $('#audit-run25').onclick=async()=>{const out=$('#audit-results25');out.textContent='Lendo registros locais...';try{
 const r=await api('/api/v25/audit');S.audit25=r;
 out.innerHTML='<div class="metrics">'+card('Avaliação completa',r.complete?'Sim':'Não','Valores incompletos são bloqueados')+card('Registros',String(r.counters.transactions),'Operações nacionais')+card('Pendências',String(r.alerts.length),'Classificadas por risco')+'</div>'+
 (r.priorities.map(x=>'<div class="watch-row"><div><b>'+esc(x.severity)+' · '+esc(x.title)+'</b><p class="small muted">'+esc(x.description)+'</p><p class="small">Próximo passo: '+esc(x.action)+'</p></div></div>').join('')||'<p>Sem alertas detectados nesta varredura.</p>')+
 '<h3>Alternativas para cada lacuna</h3>'+(r.alternatives||[]).map(a=>'<p class="small"><b>'+esc(a.need)+'</b>: '+a.options.map(esc).join(' · ')+'</p>').join('')+'<p class="small muted">'+esc(r.disclaimer)+'</p>';
 }catch(e){out.textContent=e.message;toast(e.message,true);}};
 $('#audit-export25').onclick=()=>{if(!S.audit25)return toast('Execute a auditoria antes de exportar.',true);download('metrics-auditoria-'+today()+'.json',JSON.stringify(S.audit25,null,2),'application/json');};
}};
/* Metrics 2.6: progressive onboarding and evidence-first insights. No shell execution. */
NAV.push(['explore26','▥','Análise avançada'],['guide26','⚙','Atualização guiada']);
const V26={portfolio:null,analysis:null,evolution:null,analysisDate:null,year:new Date().getFullYear(),system:null,comp:null};
const liteSteps26=[
 ['backup','1. Backup seguro','Em Ajustes, exporte um backup criptografado de cada carteira. Teste a recuperação em uma cópia. Nunca publique arquivos financeiros.'],
 ['copy','2. Pasta-fonte correta','Baixe o repositório oficial do seu Metrics e extraia este kit em outra pasta. Abra a raiz que contém package.json, server.mjs, src e web.'],
 ['dry','3. Simulação (--dry-run)','Execute a simulação e confira versão e arquivos que serão alterados. Nenhum arquivo deve ser modificado nessa etapa.'],
 ['close','4. Feche o Metrics','Encerre o app antes da instalação. Não atualize um EXE em execução.'],
 ['apply','5. Aplique apenas à cópia','Execute o instalador no diretório de código-fonte testado. Ele salva arquivos originais em uma pasta de recuperação irmã.'],
 ['test','6. Teste a versão instalada','Execute npm test e npm start. Confira dados em carteira de teste antes de importar dados reais.'],
 ['rollback','7. Recuperação','Se houver erro, não apague bancos. Use as cópias de .metrics-v26-recovery e o backup independente.']
];
function marks26(){try{const v=JSON.parse(localStorage.getItem('metrics-litekit-tutorial-v26')||'[]');return new Set(Array.isArray(v)?v:[]);}catch{return new Set();}}
function guideCommand26(stage){
 const prefix='node "<PASTA_DO_KIT>/instalar-metrics-28.mjs" "<PASTA_FONTE_METRICS>"';
 return stage==='dry'?prefix+' --dry-run':stage==='apply'?prefix:stage==='tests'?'npm test':stage==='launch'?'npm start':'npm run desktop:build -- --win portable --x64';
}
function guide26(){const complete=marks26();return `${head('ACADEMIA DO METRICS','Atualização guiada LiteKit','Aprenda o processo sem executar comandos ocultos nem tocar nos seus investimentos.')}<section class="card spaced"><div class="card-header"><h2>Diagnóstico local</h2><span class="pill">Não envia dados</span></div><p class="small muted">A atualização é feita numa cópia do código. O assistente ensina e verifica o ambiente, mas não executa instaladores nem substitui backups.</p><button id="guide-system26" class="btn primary">Verificar meu ambiente</button><div id="guide-system-result26" class="section-note">Verificação opcional de sistema e versão.</div><label class="field">Tipo de instalação<select id="guide-install-kind26" class="input"><option value="source">Código-fonte: Node + navegador</option><option value="desktop">Aplicativo portátil EXE Electron</option></select></label><div id="guide-kind-detail26" class="section-note"></div></section><section class="card spaced"><h2>Seu percurso de instalação</h2><p class="small muted" id="guide-progress26">${complete.size} de ${liteSteps26.length} etapas marcadas por você. A marcação não é uma validação automática.</p><div class="row-actions"><button class="btn" data-nav="settings">Ir para backup em Ajustes</button><a href="https://github.com/daadvi/Metrics-Investimentos" rel="noopener noreferrer" target="_blank">Abrir repositório público</a></div>${liteSteps26.map(([id,title,detail])=>`<div class="watch-row"><div><b>${esc(title)}</b><p class="small muted">${esc(detail)}</p><label class="small"><input type="checkbox" data-guide-step26="${esc(id)}" ${complete.has(id)?'checked':''}> Eu realizei esta etapa manualmente</label></div></div>`).join('')}</section><section class="card spaced"><h2>Comandos com explicação</h2><p class="small muted">Substitua os caminhos entre sinais angulares pelos diretórios reais. Os botões apenas copiam, não executam. Não cole códigos que você não verificou.</p>${[['dry','Simular (sem alterações)'],['apply','Aplicar no código-fonte'],['tests','Executar testes'],['launch','Iniciar localmente'],['exe','Gerar EXE em Windows']].map(([code,label])=>`<div class="watch-row"><div><b>${esc(label)}</b><p><code>${esc(guideCommand26(code))}</code></p></div><button class="btn smol" data-guide-copy26="${esc(code)}">Copiar</button></div>`).join('')}<p class="section-note">Os comandos são para o terminal na pasta correta, com Node.js compatível. Compilar EXE exige ferramentas de build; abrir o executável não modifica o código-fonte.</p></section>`;}
function allocationDisplay26(d){const a=d.allocation;return `<div class="metrics">${card('Patrimônio documentado',a.complete?BRL(a.totalBRL):'Incompleto','Nenhuma estimativa preenche lacunas')}${card('Ativos cobertos',String(a.pricedCount)+' / '+String(a.assetCount),'Preços e extratos válidos')}${card('Proventos BRL registrados',BRL(d.dividends.totalRecordedBRL),'Ano '+d.year+', não projetado')}${card('Pendências',String(d.audit.priorities.length),'Verifique fonte e data')}</div><section class="card spaced"><h2>Alocação por classe</h2><p class="small muted">${esc(a.note)}</p>${a.rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Classe</th><th>Valor documentado</th><th>Participação</th><th>Pendências</th></tr></thead><tbody>${a.rows.map(x=>`<tr><td>${esc(x.name)}</td><td>${BRL(x.knownBRL)}${x.missing?' (parcial)':''}</td><td>${x.weightPercent===null?'Indisponível':fmt(x.weightPercent,2)+'%'}${x.weightPercent===null?'':`<div style="max-width:160px;height:6px;background:var(--border,#293347);border-radius:9px"><div style="height:100%;width:${Math.max(0,Math.min(100,x.weightPercent))}%;background:#6989f7;border-radius:9px"></div></div>`}</td><td>${x.missing}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Nenhum ativo classificado.</p>'}</section>`;}
function dividendDisplay26(d){return `<section class="card spaced"><h2>Agenda e histórico de proventos, ano ${d.year}</h2><p class="small muted">${esc(d.dividends.note)}</p><div class="table-wrap"><table class="table"><thead><tr><th>Mês</th><th>Recebido registrado</th><th>Eventos cadastrados</th><th>Estimativas</th></tr></thead><tbody>${d.dividends.monthly.map(m=>`<tr><td>${esc(m.month)}</td><td>${BRL(m.receivedBRL)}</td><td>${m.announcements}</td><td>${m.estimated}</td></tr>`).join('')}</tbody></table></div></section>`;}
function evolutionGraph26(e){const points=e.points||[],valid=points.map((p,i)=>({p,i})).filter(x=>x.p.complete&&Number.isFinite(x.p.totalBRL));const miss=points.length-valid.length;if(valid.length<2)return `<section class="card spaced"><h2>Evolução patrimonial</h2><p class="small muted">Dados históricos completos insuficientes. ${miss} mês(es) sem avaliação integral. Não preencher lacunas com estimativas.</p></section>`;
 const vals=valid.map(x=>x.p.totalBRL),min=Math.min(...vals),max=Math.max(...vals),den=Math.max(1,max-min),w=720,h=210;
 const toX=i=>36+i/Math.max(1,points.length-1)*(w-65),toY=v=>h-34-(v-min)/den*(h-68);
 const segments=[];let segment=[];for(let i=0;i<points.length;i++){const p=points[i];if(p.complete&&Number.isFinite(p.totalBRL))segment.push({x:toX(i),y:toY(p.totalBRL),date:p.date,value:p.totalBRL});else if(segment.length){segments.push(segment);segment=[];}}if(segment.length)segments.push(segment);
 const lines=segments.map(z=>z.length>=2?`<polyline points="${z.map(x=>x.x.toFixed(1)+','+x.y.toFixed(1)).join(' ')}" fill="none" stroke="#7492fa" stroke-width="3" stroke-linecap="round"/>`:'').join('');
 const circles=segments.flatMap(z=>z.map(x=>`<circle cx="${x.x.toFixed(1)}" cy="${x.y.toFixed(1)}" r="3" fill="#a5b4fc"><title>${esc(x.date)}: ${esc(BRL(x.value))}</title></circle>`)).join('');
 return `<section class="card spaced"><h2>Evolução documentada: últimos ${points.length} meses</h2><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Evolução com interrupções quando há dados ausentes" style="width:100%;max-height:270px"><line x1="36" y1="${h-30}" x2="${w-20}" y2="${h-30}" stroke="#718096" opacity=".45"/>${lines}${circles}<text x="36" y="14" fill="currentColor" font-size="13">${esc(BRL(max))}</text><text x="36" y="${h-9}" fill="currentColor" font-size="13">${esc(BRL(min))}</text></svg><p class="small muted">${miss} mês(es) incompleto(s), mostrados como interrupções na linha. Esta curva representa saldos, não lucro, TWR ou retorno descontado dos aportes. ${esc(e.warning)}</p></section>`;
}
function sectorDisplay26(d){const s=d.sectors;return `<section class="card spaced"><h2>Exposição por setor cadastrado</h2><p class="small muted">${esc(s.note)} ${s.unclassifiedAssets} ativo(s) sem classificação.</p>${s.rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Setor</th><th>Valor conhecido</th><th>Ativos</th><th>Sem preço</th></tr></thead><tbody>${s.rows.map(x=>`<tr><td>${esc(x.sector)}</td><td>${BRL(x.knownBRL)}</td><td>${x.assets}</td><td>${x.missingValue}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Cadastre setores nas fichas para acompanhar a exposição.</p>'}</section>`;}
function incomePatternDisplay26(d){const p=d.historicalIncome;return `<section class="card spaced"><h2>Radar histórico de pagamentos</h2><p class="small muted">${esc(p.warning)}</p><div class="table-wrap"><table class="table"><thead><tr><th>Mês</th><th>Anos com registros</th><th>Total histórico cadastrado</th></tr></thead><tbody>${p.rows.map(x=>`<tr><td>${String(x.month).padStart(2,'0')}</td><td>${x.recordedYears.length===0?'Nenhum':x.recordedYears.join(', ')}</td><td>${BRL(x.historicalBRL)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function compareForm26(d){const opts=d.comparableTickers.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('');return `<section class="card spaced"><h2>Comparador de fundamentos documentados</h2><p class="small muted">Compare apenas dados cadastrados com origem. Períodos diferentes não são tratados como equivalentes.</p><div class="row-actions"><label class="field">Ativo A<select id="compare-a26" class="input"><option value="">Selecione</option>${opts}</select></label><label class="field">Ativo B<select id="compare-b26" class="input"><option value="">Selecione</option>${opts}</select></label><button class="btn" id="compare-run26">Comparar</button></div><div id="compare-result26" class="section-note">Selecione dois ativos com ficha registrada.</div></section>`;}
