async function loadExplore26(){const out=$('#explore-report26');if(!out)return;out.textContent='Consolidando registros locais com datas e fontes...';try{const date=$('#explore-date26').value,year=$('#explore-year26').value;const [d,evolution]=await Promise.all([api('/api/v26/analytics?date='+encodeURIComponent(date)+'&year='+encodeURIComponent(year)),api('/api/v24/evolution?date='+encodeURIComponent(date)+'&months=12')]);V26.analysis=d;V26.evolution=evolution;V26.analysisDate=date;V26.year=Number(year);out.innerHTML=allocationDisplay26(d)+evolutionGraph26(evolution)+sectorDisplay26(d)+dividendDisplay26(d)+incomePatternDisplay26(d)+compareForm26(d)+issuesDisplay26(d);$('#compare-run26').onclick=async()=>{const a=$('#compare-a26').value,b=$('#compare-b26').value,el=$('#compare-result26');if(!a||!b||a===b){el.textContent='Selecione dois ativos diferentes.';return;}try{const c=await api('/api/v26/compare?tickers='+encodeURIComponent(a+','+b));const fields=[['dy12','DY 12 meses (%)'],['dividend','Provento unitário'],['equity','Patrimônio declarado'],['vacancy','Vacância (%)'],['debt','Dívida declarada']];el.innerHTML=`<div class="table-wrap"><table class="table"><thead><tr><th>Indicador</th>${c.found.map(x=>`<th>${esc(x.ticker)}</th>`).join('')}</tr></thead><tbody>${fields.map(([key,name])=>`<tr><td>${esc(name)}</td>${c.found.map(x=>`<td>${x.metrics[key]===null?'Não informado':fmt(x.metrics[key],2)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="small muted">${c.found.map(x=>`${esc(x.ticker)} · ${esc(x.asOf||'sem data')} · ${esc(x.source||'sem fonte')}`).join(' | ')}</p><p class="small muted">${esc(c.note)}</p>`;}catch(e){el.textContent=e.message;}};}catch(e){out.textContent=e.message;toast(e.message,true);}}
function bindExplore26(){const form=$('#explore-filter26');if(!form)return;form.onsubmit=e=>{e.preventDefault();loadExplore26();};$('#explore-export26').onclick=()=>{if(!V26.analysis||V26.analysisDate!==$('#explore-date26').value||V26.year!==Number($('#explore-year26').value))return toast('Atualize a análise dos filtros selecionados antes de exportar.',true);download('metrics-analise-'+V26.analysisDate+'.json',JSON.stringify({...V26.analysis,evolution:V26.evolution},null,2),'application/json');};}
