function bindGuide26(){const el=$('#guide-system26');if(!el)return;const kind=$('#guide-install-kind26'),detail=$('#guide-kind-detail26');const describe=()=>{detail.textContent=kind.value==='desktop'?'Instalação EXE: o kit modifica o código-fonte, não o executável instalado. Faça backup, aplique à cópia do código, rode os testes e compile um novo EXE.':'Modo leve: exige Node 22.13+ e navegador instalado. O instalador trabalha na cópia do fonte. O botão não altera seu banco.';};kind.onchange=describe;describe();el.onclick=async()=>{const out=$('#guide-system-result26');out.textContent='Verificando versão e configuração local...';try{const r=await api('/api/v26/system');V26.system=r;out.textContent=`Metrics ${r.version} · ${r.platform} · Node ${r.nodeVersion} · Node compatível: ${r.nodeCompatible?'sim':'não'} · Cache seletivo para banco criptografado: ${r.storageCache.enabled?'disponível':'desativado'}. ${r.warning}`;}catch(e){out.textContent=e.message;}};$('[data-guide-step26]').forEach(el=>el.onchange=()=>{const done=marks26();if(el.checked)done.add(el.dataset.guideStep26);else done.delete(el.dataset.guideStep26);try{localStorage.setItem('metrics-litekit-tutorial-v26',JSON.stringify([...done]));}catch{};const progress=$('#guide-progress26');if(progress)progress.textContent=done.size+' de '+liteSteps26.length+' etapas marcadas manualmente (não verificadas).';});$('[data-guide-copy26]').forEach(el=>el.onclick=()=>copyGuide26(el.dataset.guideCopy26));}
