function history27(){return `${head('DADOS DA CARTEIRA','Histórico paginado','Consultas pequenas, com filtros e sem carregar a lista inteira na tela.')}<section class="card spaced"><form id="history-form27" class="form-grid two"><label class="field">Tipo de histórico<select class="input" name="kind"><option value="transactions">Operações</option><option value="quotes">Cotações históricas</option><option value="foreign">Operações no exterior</option><option value="events">Eventos de proventos</option><option value="evidence">Informes fiscais</option><option value="flows">Aportes e retiradas</option><option value="checks">Documentos CVM</option></select></label><label class="field">Ativo<input class="input" name="ticker" maxlength="25" placeholder="Opcional"></label><label class="field">De<input class="input" name="from" type="date"></label><label class="field">Até<input class="input" name="to" type="date"></label><label class="field">Itens por página<select class="input" name="limit"><option value="25">25</option><option value="50" selected>50</option><option value="100">100</option></select></label><button class="btn primary" type="submit">Consultar histórico</button></form><div class="row-actions spaced-mini"><button class="btn" id="history-more27" type="button" disabled>Próxima página</button><button class="btn" id="history-clear27" type="button">Limpar resultado</button></div><div id="history-out27" class="section-note">Escolha os filtros e clique em Consultar.</div></section>`;}
function bindHistory27(){const f=$('#history-form27');if(!f)return;const out=$('#history-out27'),more=$('#history-more27');let serial=0;const load=async(reset=true)=>{const token=++serial;try{if(reset){V27.cursor=null;V27.query=Object.fromEntries(new FormData(f));}const q=new URLSearchParams(V27.query);if(V27.cursor)q.set('cursor',V27.cursor);out.textContent='Carregando página local...';const r=await api('/api/v28/history?'+q);if(token!==serial)return;V27.history=r;V27.cursor=r.nextCursor;more.disabled=!r.hasMore;out.innerHTML=`<p class="small muted">${r.rows.length} registros nesta página, ${r.totalFiltered===null?'total não calculado':r.totalFiltered+' encontrados'}. ${esc(r.warning)}</p>${r.rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Ativo</th><th>Tipo</th><th>Quantidade/valor</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td>${esc(String(x.date||x.asOf||x.deliveryDate||'—'))}</td><td>${esc(x.ticker||x.assetKey||'—')}</td><td>${esc(x.type||x.nature||x.kind||'—')}</td><td>${esc(String(x.quantity??x.amount??x.value??'—'))}</td></tr>`).join('')}</tbody></table></div>`:'<p>Nenhum item para esses filtros.</p>'}`;}catch(e){out.textContent=e.message;toast(e.message,true);}};f.onsubmit=e=>{e.preventDefault();load(true);};more.onclick=()=>load(false);$('#history-clear27').onclick=()=>{serial++;V27.cursor=null;V27.history=null;more.disabled=true;out.textContent='Consulta limpa.';};}
function returns27(){return `${head('ANÁLISE QUANTITATIVA','Rentabilidade multiclasse','Modified Dietz: separa entradas externas das oscilações de patrimônio, somente com documentação.')}<section class="card spaced"><p class="small muted">Para avaliar retornos, registre preços e saldos de cada classe e os aportes/retiradas externos. Uma compra dentro da carteira não é aporte. A assinatura documental abaixo é apenas sua confirmação, não auditoria profissional.</p><form id="returns-filter27" class="form-grid two"><label class="field">Data final<input class="input" name="date" type="date" value="${today()}" required></label><label class="field">Janela<select class="input" name="months"><option value="6">6 meses</option><option value="12" selected>12 meses</option><option value="24">24 meses</option><option value="36">36 meses</option></select></label><button class="btn primary" type="submit">Calcular com dados completos</button></form><div id="returns-out27" class="section-note">Quando faltar extrato, caixa, preço ou câmbio, o retorno ficará indisponível.</div></section><section class="card spaced"><h2>Confirmar cobertura de fluxos externos</h2><p class="small muted">Só confirme quando tiver conferido depósitos e retiradas de todas as contas envolvidas no período. A declaração não transforma dados incompletos em corretos.</p><form id="flow-coverage27" class="form-grid two"><label class="field">Início<input class="input" type="date" name="from" required></label><label class="field">Fim<input class="input" type="date" name="to" required></label><label class="field wide">Referência dos extratos conferidos<input class="input" name="source" maxlength="200" minlength="8" required placeholder="Ex.: extratos de todas as corretoras, jan-dez 2026"></label><button class="btn" type="submit">Registrar conferência manual</button></form><p class="small muted" id="flow-msg27"></p></section>`;}
function bindReturns27(){const f=$('#returns-filter27');if(!f)return;f.onsubmit=async e=>{e.preventDefault();const data=new URLSearchParams(new FormData(f));const o=$('#returns-out27');o.textContent='Recalculando patrimônio datado...';try{const d=await api('/api/v27/performance?'+data);V27.analysis=d;o.innerHTML=`<div class="metrics">${card('Meses avaliados',d.periods.length,'Períodos consecutivos')}${card('Períodos completos',d.completePeriods,'Com cobertura de preços e fluxos')}${card('Retorno acumulado estimado',d.linkedApproximatePercent===null?'Indisponível':fmt(d.linkedApproximatePercent,3)+'%','Sem pontes sobre lacunas')}</div><p class="small muted">${esc(d.warning)}</p><div class="table-wrap"><table class="table"><thead><tr><th>Período</th><th>Retorno estimado</th><th>Aportes líquidos externos</th><th>Situação</th></tr></thead><tbody>${d.periods.map(p=>`<tr><td>${esc(p.from)} a ${esc(p.to)}</td><td>${p.returnPercent===null?'—':fmt(p.returnPercent,3)+'%'}</td><td>${p.netExternalBRL===undefined?'—':BRL(p.netExternalBRL)}</td><td>${esc(p.status)}</td></tr>`).join('')}</tbody></table></div>`;}catch(err){o.textContent=err.message;}};$('#flow-coverage27').onsubmit=async e=>{e.preventDefault();if(!confirm('Você conferiu os extratos e registrou todas as entradas e saídas externas do período? Esta confirmação não é uma auditoria.'))return;const o=$('#flow-msg27');try{const data=Object.fromEntries(new FormData(e.currentTarget));await api('/api/v27/flows/confirm',{method:'POST',data});o.textContent='Cobertura declarada por você. Atualize a análise e confira os valores apresentados.';}catch(err){o.textContent=err.message;}};}
function reconcile27(){return `${head('INTEGRIDADE FINANCEIRA','Importação assistida','Prévia, erros e comparação com o livro, sempre antes de qualquer lançamento.')}<section class="card spaced"><h2>Conferir CSV/TSV da corretora</h2><p class="small muted">Aceita arquivos CSV/TSV de até 2 MB com colunas de data, ticker, tipo, quantidade e preço/valor. O arquivo é analisado localmente. Arquivos de custódia devem seguir a importação de posições, não esta etapa de negociações.</p><label class="field">Arquivo local<input id="reconcile-file27" class="input" type="file" accept=".csv,.tsv,.txt"></label><details class="spaced-mini"><summary>Mapeamento manual de colunas (opcional)</summary><p class="small muted">Se o reconhecimento automático falhar, escreva o título exato da coluna que aparece no CSV. Deixe em branco os demais campos.</p><form id="reconcile-columns27" class="form-grid two">${[['date','Data'],['ticker','Ticker/código'],['type','Tipo de movimentação'],['quantity','Quantidade'],['price','Preço unitário'],['fee','Taxas'],['amount','Valor do provento']].map(([key,label])=>`<label class="field">${esc(label)}<input class="input" name="${esc(key)}" placeholder="Nome da coluna no CSV"></label>`).join('')}</form></details><div class="row-actions spaced-mini"><button id="preview-reconcile27" class="btn primary">Pré-visualizar</button><button id="compare-reconcile27" class="btn" disabled>Comparar com lançamentos existentes</button><button class="btn" data-nav="import">Voltar à importação B3</button></div><div id="reconcile-out27" class="section-note">Nenhuma operação será incluída automaticamente nesta tela.</div></section>`;}
function bindReconcile27(){const file=$('#reconcile-file27'),preview=$('#preview-reconcile27'),compare=$('#compare-reconcile27'),out=$('#reconcile-out27');if(!file)return;const reset=()=>{V27.preview=null;compare.disabled=true;out.textContent='Arquivo ou mapeamento alterado. Clique em Pré-visualizar.';};file.onchange=reset;$('#reconcile-columns27').oninput=reset;preview.onclick=async()=>{const selected=file.files[0];if(!selected)return out.textContent='Selecione um CSV/TSV.';if(selected.size>2_000_000)return out.textContent='O arquivo excede 2 MB.';out.textContent='Verificando colunas, datas e valores...';try{const data=await api('/api/v27/import/preview',{method:'POST',data:{text:await selected.text(),source:selected.name,columns:Object.fromEntries([...new FormData($('#reconcile-columns27'))].filter(([,v])=>String(v).trim()))}});V27.preview=data;compare.disabled=!data.acceptedCount;out.innerHTML=`<p><b>${data.acceptedCount}</b> candidatos e <b>${data.rejectedCount}</b> linhas para revisão. Nenhum registro foi lançado.</p><p class="small muted">Colunas reconhecidas: ${esc(JSON.stringify(data.mapping))}. SHA-256: ${esc(data.sourceHash)}</p>${data.rejected.length?`<h3>Linhas rejeitadas</h3>${data.rejected.slice(0,15).map(x=>`<p class="small">Linha ${x.line}: ${esc(x.reason)}</p>`).join('')}`:''}<p class="small muted">${esc(data.warnings.join(' '))}</p>`;}catch(err){out.textContent=err.message;}};compare.onclick=async()=>{if(!V27.preview)return;out.textContent='Comparando os candidatos com o livro existente...';try{const r=await api('/api/v27/import/reconcile',{method:'POST',data:{candidates:V27.preview.accepted}});out.innerHTML=`<p>${r.total} candidatos. Já lançados: ${r.counts.ALREADY_REGISTERED}; divergentes: ${r.counts.REVIEW_DIFFERENCE}; ausentes: ${r.counts.NOT_FOUND}; duplicados no arquivo: ${r.counts.DUPLICATE_IN_FILE}.</p><p class="small muted">${esc(r.note)}</p><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Ativo</th><th>Tipo</th><th>Conciliação</th></tr></thead><tbody>${r.rows.slice(0,150).map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.ticker)}</td><td>${esc(x.type)}</td><td>${esc(x.status)}</td></tr>`).join('')}</tbody></table></div><p>Para efetivar uma importação, use a aba Importar B3 e revise cuidadosamente o lote antes de confirmar.</p>`;}catch(err){out.textContent=err.message;}};}
function storage27(){return `${head('PROTEÇÃO DOS DADOS','Armazenamento seguro','Migração opcional de SQLite monolítico para registros por carteira, coleção e item.')}<section class="card spaced"><p class="small muted">A estrutura legada continuará funcionando. A nova estrutura exige seu consentimento explícito e produz um backup SQLite local antes de migrar. Verifique também o seu backup criptografado em Ajustes, testado em uma instalação separada.</p><button class="btn" id="storage-check27">Verificar modo do banco</button><div id="storage-out27" class="section-note">Ainda não consultado.</div><div class="row-actions spaced-mini"><button class="btn primary" id="storage-migrate27">Migrar após realizar backups</button><button class="btn" data-nav="settings">Exportar backup em Ajustes</button></div><p class="small muted">A migração não é um recurso de limpeza de dados. Não execute sem ter como restaurar o aplicativo anterior e o banco.</p></section>`;}
function bindStorage27(){const query=$('#storage-check27');if(!query)return;const out=$('#storage-out27');const check=async()=>{try{const r=await api('/api/v27/storage');V27.storage=r;out.textContent=`Modo: ${r.normalized?'relacional 2.7':'legado JSON no SQLite'}. Criptografado: ${r.encrypted?'sim':'não'}. Registros relacionais: ${r.entries}. ${r.warning}`;}catch(err){out.textContent=err.message;}};query.onclick=check;$('#storage-migrate27').onclick=async()=>{if(!confirm('Antes de normalizar, exporte backups protegidos de cada carteira e teste uma restauração em ambiente separado. Você já fez isso?'))return;const confirmation=prompt('Para iniciar a migração protegida, digite NORMALIZAR:');if(confirmation!=='NORMALIZAR')return;out.textContent='Criando cópia SQLite e verificando integridade...';try{const r=await api('/api/v27/storage/migrate',{method:'POST',data:{confirmation}});out.textContent=r.alreadyNormalized?'O banco já está normalizado.':`Normalização concluída. Backup local criado em ${r.backupPath}. Guarde também seu backup criptografado independente.`;}catch(err){out.textContent=err.message;toast(err.message,true);}};}
