function bindSourcesV13(){
 const quarter=$('#cvm-quarterly-form-v13');if(!quarter)return;
 const text=$('#cvm-quarterly-result-v13');const map=()=>{const data=new FormData(quarter),cnpj=String(data.get('cnpj')||'').replace(/\D/g,''),ticker=String(data.get('ticker')||'').trim().toUpperCase();if(cnpj.length!==14)throw Error('CNPJ precisa de 14 dígitos e será validado pelo servidor.');if(!ticker)throw Error('Ticker é obrigatório.');return {tickerMap:{[cnpj]:ticker},year:data.get('year')}};
 const file=async()=>{const f=$('#cvm-quarterly-file-v13').files?.[0];if(!f)throw Error('Selecione primeiro um CSV/ZIP trimestral.');if(f.size>15*1024*1024)throw Error('Arquivo acima de 15 MB.');const bytes=new Uint8Array(await f.arrayBuffer());let data='';for(let i=0;i<bytes.length;i+=16384)data+=String.fromCharCode(...bytes.subarray(i,i+16384));return {...map(),data:btoa(data)};};
 for(const [id,path] of [['cvm-quarterly-preview-v13','/api/official/cvm-quarterly/preview'],['cvm-quarterly-import-v13','/api/official/cvm-quarterly/import']])$('#'+id).onclick=async()=>{try{text.textContent='Lendo informe...';const r=await api(path,{method:'POST',data:await file()});text.textContent=r.inserted!==undefined?`${r.inserted} registros salvos (${r.duplicates} já existentes). ${r.warning}`:`${r.entries.length} registros encontrados em ${r.filesRead} CSV(s). ${r.warning}`;if(r.inserted!==undefined){await update();render();}}catch(e){text.textContent=e.message;toast(e.message,true);}};
 $('#cvm-quarterly-download-v13').onclick=async()=>{try{text.textContent='Consultando dados CVM...';const r=await api('/api/official/cvm-quarterly/download',{method:'POST',data:map()});text.textContent=`${r.inserted} registros; fonte ${r.url}`;await update();render();}catch(e){text.textContent=e.message;toast(e.message,true);}};
 $('#provider-dividend-form-v13').onsubmit=async e=>{e.preventDefault();const message=$('#provider-dividend-result-v13'),preview=$('#provider-dividend-preview-v13');try{message.textContent='Consultando fornecedor externo...';const fields=formValue(e.currentTarget);const result=await api('/api/dividends/brapi-preview',{method:'POST',data:fields});message.textContent=`${result.observations.length} observações. ${result.warning}`;preview.innerHTML=`<button id="save-dividend-v13" class="btn">Salvar observações após conferência</button><div class="table-wrap"><table class="table"><thead><tr><th>Ativo</th><th>Valor</th><th>Referência</th><th>Pagamento</th><th>Confiabilidade</th></tr></thead><tbody>${result.observations.slice(0,80).map(x=>`<tr><td>${esc(x.ticker)}</td><td>${BRL(x.rate)}</td><td>${esc(x.recordDate||'Não informada')}</td><td>${esc(x.paymentDate||'Não informado')}</td><td>${esc(x.status)}</td></tr>`).join('')}</tbody></table></div>`;$('#save-dividend-v13').onclick=async()=>{try{const payload={kind:fields.kind,dividends:result.observations.map(x=>({symbol:x.ticker,label:x.label,rate:x.rate,lastDatePrior:x.recordDate,paymentDate:x.paymentDate,remarks:x.remarks}))};const r=await api('/api/dividends/brapi-save',{method:'POST',data:payload});toast(`${r.added} observações armazenadas; nenhuma confirmada oficialmente.`);await update();render();}catch(error){toast(error.message,true);}};}catch(error){message.textContent=error.message;toast(error.message,true);}};
}
