 const form=$('#ipe-form-v14'),out=$('#ipe-result-v14');const config=()=>{const p=formValue(form),cnpj=String(p.cnpj||'').replace(/\D/g,'');if(cnpj.length!==14)throw Error('Informe CNPJ com 14 dígitos válidos.');return {tickerMap:{[cnpj]:String(p.ticker||'').toUpperCase().trim()},year:Number(p.year)};};
 const fileData=async()=>{const f=$('#ipe-upload-v14').files?.[0];if(!f)throw Error('Selecione um ZIP ou CSV IPE.');if(f.size>15*1024*1024)throw Error('Arquivo maior que 15MB.');return {...config(),data:await toBase64(f)};};
 for(const [id,url] of [['ipe-preview-v14','/api/official/ipe/preview'],['ipe-import-v14','/api/official/ipe/import']])$('#'+id).onclick=async()=>{try{out.textContent='Lendo índices CVM...';const result=await api(url,{method:'POST',data:await fileData()});out.textContent=id.includes('preview')?`${result.entries.length} documentos detectados. Nenhuma alteração gravada.`:`${result.added} comunicados adicionados; ${result.total} no arquivo local. ${result.warning}`;if(result.added!==undefined){await refreshProvidersV14();render();}}catch(error){out.textContent=error.message;toast(error.message,true);}};
