 for(const [id,endpoint] of [['dfp-preview-v14','/api/official/dfp/preview'],['dfp-import-v14','/api/official/dfp/import']])$('#'+id).onclick=async()=>{try{dfpResult.textContent='Validando contas e unidades do DFP...';const r=await api(endpoint,{method:'POST',data:await dfpFile()});dfpResult.textContent=(r.entries?`${r.entries.length} contas na prévia (não gravadas).`:`${r.added} contas adicionadas; ${r.revised} contas retificadas.`)+' '+r.warning;}catch(e){dfpResult.textContent=e.message;toast(e.message,true);}};
